import * as React from "react"
import {
  AiChat02Icon,
  Alert02Icon,
  SparklesIcon,
} from "@hugeicons/core-free-icons"
import { getHTMLFromFragment, type Editor } from "@tiptap/core"
import { cn } from "cn"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Kbd } from "@/components/ui/kbd"
import { Skeleton } from "@/components/ui/skeleton"
import { Spinner } from "@/components/ui/spinner"
import { Icon } from "../icon"
import type { AIController } from "./ai/ai-controller"
import type { AIResultMode, AIState } from "./ai/ai-types"
import { useRichTextEditorContext } from "./context"
import { closeOpenMarkdown, parseMarkdown } from "./core/markdown"
import { formatShortcut } from "./shortcuts"
import type { UrlPolicy } from "./types"

/** What a custom AI panel (`components.AIPreview`) receives. */
export interface AIPreviewProps {
  state: AIState
  ai: AIController
  editor: Editor
}

const ANNOUNCEMENTS: Partial<Record<AIState["status"], string>> = {
  running: "The AI is writing.",
  ready: "The AI's answer is ready. Accept it or discard it.",
  conflict:
    "The text changed while the AI worked. Choose where the answer goes.",
}

/**
 * Renders streamed Markdown with the editor's own schema and typography,
 * without touching the document. Unfinished syntax is closed first.
 */
function MarkdownPreview({
  markdown,
  editor,
  policy,
}: {
  markdown: string
  editor: Editor
  policy: UrlPolicy
}) {
  const html = React.useMemo(() => {
    try {
      const { doc } = parseMarkdown(editor, closeOpenMarkdown(markdown), policy)
      return getHTMLFromFragment(
        editor.schema.nodeFromJSON(doc).content,
        editor.schema
      )
    } catch {
      return null
    }
  }, [markdown, editor, policy])
  if (html === null) {
    return (
      <pre className="font-mono text-xs whitespace-pre-wrap">{markdown}</pre>
    )
  }
  return (
    <div className="rich-text">
      {/* The editor's schema produced this HTML, so it holds only what the
          document could: no scripts, and links and images the policy allows. */}
      <div
        className="ProseMirror rich-text-preview"
        dangerouslySetInnerHTML={{ __html: html }}
      />
    </div>
  )
}

function acceptLabel(mode: AIResultMode, hasSelection: boolean) {
  if (mode === "replace") return "Replace selection"
  if (mode === "append") return "Add to the end"
  return hasSelection ? "Insert below" : "Insert"
}

/**
 * The AI panel under the text: the "Ask AI…" prompt, the answer as it
 * streams, then Accept, Try again and Discard. A conflict (the text changed
 * meanwhile) offers the caret instead. Status changes are announced, ⌘Enter
 * accepts and Escape cancels or discards.
 */
export function AIResponsePreview({ className }: { className?: string }) {
  const { editor, ai, controller, urlPolicy } = useRichTextEditorContext()
  const state = React.useSyncExternalStore(ai.subscribe, ai.getState)
  const panelRef = React.useRef<HTMLDivElement>(null)
  const primaryRef = React.useRef<HTMLButtonElement>(null)
  const [prompt, setPrompt] = React.useState("")
  const [copied, setCopied] = React.useState(false)
  const { status } = state

  // With focus in the panel (Stop, say), it moves to the answer's main
  // button once that exists; someone typing in the text keeps typing.
  React.useEffect(() => {
    const active = document.activeElement
    const inPanel = Boolean(active && panelRef.current?.contains(active))
    if (
      (status === "ready" || status === "conflict") &&
      (inPanel || active === document.body)
    ) {
      primaryRef.current?.focus()
    }
  }, [status])

  const close = (action: () => void) => {
    const inPanel = panelRef.current?.contains(document.activeElement)
    action()
    setPrompt("")
    if (inPanel) controller.focus()
  }

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(state.markdown)
      setCopied(true)
      setTimeout(() => setCopied(false), 1500)
    } catch {
      // The buttons stay; the person can still accept or select the text.
    }
  }

  const accept = (target?: AIResultMode | "cursor") => {
    const inPanel = panelRef.current?.contains(document.activeElement)
    if (ai.accept(target) && inPanel) controller.focus()
  }

  const onKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === "Escape") {
      event.preventDefault()
      close(() => (status === "running" ? ai.cancel() : ai.reject()))
    } else if (
      event.key === "Enter" &&
      (event.metaKey || event.ctrlKey) &&
      status === "ready"
    ) {
      event.preventDefault()
      accept()
    }
  }

  const announcement =
    status === "error"
      ? `The AI request failed: ${state.error ?? ""}`
      : (ANNOUNCEMENTS[status] ?? "")

  return (
    <>
      <div role="status" aria-live="polite" className="sr-only">
        {announcement}
      </div>
      {status !== "idle" && (
        <div
          ref={panelRef}
          data-slot="rich-text-ai"
          role="region"
          aria-label="AI answer"
          onKeyDown={onKeyDown}
          className={cn(
            "flex flex-col gap-2 border-t border-border bg-muted/40 px-3 py-2.5",
            className
          )}
        >
          {status === "prompt" ? (
            <form
              className="flex items-center gap-2"
              onSubmit={(event) => {
                event.preventDefault()
                if (!prompt.trim()) return
                void ai.submitPrompt(prompt)
                // The next prompt box starts empty.
                setPrompt("")
              }}
            >
              <Icon
                icon={AiChat02Icon}
                className="shrink-0 text-muted-foreground"
              />
              <Input
                autoFocus
                value={prompt}
                onChange={(event) => setPrompt(event.target.value)}
                placeholder={
                  state.action?.placeholder ??
                  (state.hasSelection
                    ? "What should the AI do with the selection?"
                    : "What should the AI write here?")
                }
                aria-label={`What ${state.action?.label.replace(/…$/, "") ?? "the AI"} should do`}
                className="h-7 flex-1 bg-background"
              />
              <Button type="submit" size="sm" disabled={!prompt.trim()}>
                Generate
              </Button>
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={() => close(() => ai.cancel())}
              >
                Cancel
              </Button>
            </form>
          ) : (
            <>
              <div className="flex items-center gap-2 text-xs">
                {status === "running" ? (
                  <Spinner className="text-muted-foreground" />
                ) : status === "error" || status === "conflict" ? (
                  <Icon
                    icon={Alert02Icon}
                    size={15}
                    className="text-destructive"
                  />
                ) : (
                  <Icon
                    icon={SparklesIcon}
                    size={15}
                    className="text-muted-foreground"
                  />
                )}
                <span className="font-medium text-foreground">
                  {state.action?.label.replace(/…$/, "") ?? "AI"}
                </span>
                {state.instruction && (
                  <span className="min-w-0 truncate text-muted-foreground">
                    “{state.instruction}”
                  </span>
                )}
                <span className="ml-auto text-2xs text-subtle">
                  {status === "running"
                    ? "Writing…"
                    : status === "ready"
                      ? "Review before it goes in"
                      : null}
                </span>
              </div>

              {status === "error" ? (
                <p className="text-xs text-destructive">{state.error}</p>
              ) : status === "running" && !state.markdown ? (
                <div aria-hidden className="flex flex-col gap-1.5 py-1">
                  <Skeleton className="h-3.5 w-3/4" />
                  <Skeleton className="h-3.5 w-1/2" />
                </div>
              ) : (
                <div
                  tabIndex={0}
                  aria-label="Answer preview"
                  className="max-h-64 overflow-y-auto rounded-(--radius-card) border border-border bg-background"
                >
                  <MarkdownPreview
                    markdown={state.markdown}
                    editor={editor}
                    policy={urlPolicy()}
                  />
                </div>
              )}

              {status === "conflict" && (
                <p className="text-xs text-muted-foreground">
                  The text this was for changed while the AI worked, so it
                  wasn't overwritten. Put the answer at the caret instead, or
                  copy it.
                </p>
              )}

              <div className="flex flex-wrap items-center gap-1.5">
                {status === "running" && (
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => close(() => ai.cancel())}
                  >
                    <Icon icon="stop" data-icon="inline-start" />
                    Stop
                  </Button>
                )}
                {status === "ready" &&
                  (state.mode === "preview" ? (
                    <>
                      {state.hasSelection && (
                        <Button
                          ref={primaryRef}
                          type="button"
                          size="sm"
                          onClick={() => accept("replace")}
                        >
                          Replace selection
                        </Button>
                      )}
                      <Button
                        ref={state.hasSelection ? undefined : primaryRef}
                        type="button"
                        size="sm"
                        variant={state.hasSelection ? "outline" : "default"}
                        onClick={() => accept("insert")}
                      >
                        {state.hasSelection ? "Insert below" : "Insert"}
                      </Button>
                    </>
                  ) : (
                    <Button
                      ref={primaryRef}
                      type="button"
                      size="sm"
                      onClick={() => accept()}
                    >
                      {acceptLabel(state.mode, state.hasSelection)}
                      <Kbd className="ml-1 bg-transparent text-current opacity-70">
                        {formatShortcut("Mod-Enter")}
                      </Kbd>
                    </Button>
                  ))}
                {status === "conflict" && (
                  <Button
                    ref={primaryRef}
                    type="button"
                    size="sm"
                    onClick={() => accept("cursor")}
                  >
                    Insert at caret
                  </Button>
                )}
                {(status === "ready" || status === "conflict") && (
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() => void copy()}
                  >
                    <Icon icon="copy" data-icon="inline-start" />
                    {copied ? "Copied" : "Copy"}
                  </Button>
                )}
                {(status === "ready" || status === "error") && (
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() => void ai.regenerate()}
                  >
                    <Icon icon="refresh" data-icon="inline-start" />
                    Try again
                  </Button>
                )}
                {status !== "running" && (
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    className="ml-auto"
                    onClick={() => close(() => ai.reject())}
                  >
                    {status === "error" ? "Dismiss" : "Discard"}
                  </Button>
                )}
              </div>
            </>
          )}
        </div>
      )}
    </>
  )
}

import {
  AiChat02Icon,
  ArrowExpandIcon,
  ArrowRight02Icon,
  Note01Icon,
  PencilEdit02Icon,
  SparklesIcon,
  Tick02Icon,
} from "@hugeicons/core-free-icons"

import type { EditorAction, EditorUiHandlers } from "../types.ts"
import { ASK_AI, type AIController } from "./ai-controller.ts"

const ICONS: Record<string, EditorAction["icon"]> = {
  ask: AiChat02Icon,
  rewrite: PencilEdit02Icon,
  fix: Tick02Icon,
  summarize: Note01Icon,
  expand: ArrowExpandIcon,
  continue: ArrowRight02Icon,
}

/**
 * The AI commands as editor actions (`ai.<id>`), so menus, toolbars, the `/`
 * menu and `executeAction` reach them like any other action. "Ask AI…" and
 * any action that asks for an instruction open the prompt box instead of
 * running straight away.
 */
export function createAIActions(
  ai: AIController,
  ui: () => EditorUiHandlers
): EditorAction[] {
  return ai.definitions().map((definition): EditorAction => ({
    id: `ai.${definition.id}`,
    label: definition.label,
    icon: ICONS[definition.id] ?? SparklesIcon,
    group: "AI",
    description: definition.description,
    keywords: ["ai", "assistant", definition.id],
    slashCommand: !definition.requiresSelection,
    isEnabled: (context) =>
      !definition.requiresSelection || !context.selection.empty,
    execute: async (context) => {
      const { from, to } = context.selection
      if (definition.id === ASK_AI.id || definition.askInstruction) {
        ai.openPrompt({ from, to }, definition.id)
        ui().askAI()
        return
      }
      await ai.start(definition.id, { range: { from, to } })
    },
  }))
}

import type { Editor } from "@tiptap/core"

import { createBookmark } from "../core/selection-manager.ts"
import type {
  EditorBookmark,
  EditorController,
  EditorError,
  EditorRange,
} from "../types.ts"
import { ASK_AI, DEFAULT_AI_ACTIONS } from "./ai-defaults.ts"
import {
  IDLE_AI_STATE,
  type AIActionDefinition,
  type AIRequest,
  type AIResult,
  type AIResultMode,
  type AIState,
  type AIStreamEvent,
  type EditorAIConfig,
} from "./ai-types.ts"

export { ASK_AI, DEFAULT_AI_ACTIONS }

export interface AIHost {
  controller: EditorController
  getEditor: () => Editor | null
  getConfig: () => EditorAIConfig | undefined
  onError: (error: EditorError) => void
}

export function isAsyncIterable<T>(value: unknown): value is AsyncIterable<T> {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof (value as AsyncIterable<T>)[Symbol.asyncIterator] === "function"
  )
}

// Streamed text reaches the preview at most this often, however fast the
// tokens arrive.
const FLUSH_MS = 60

/**
 * Runs AI actions against the host's `execute` callback: captures the
 * selection as a bookmark, streams the answer into a buffer the preview
 * shows, and on approval writes it where the action said, unless that text
 * has changed meanwhile, in which case the person picks a new place.
 * The document is never touched while an answer streams.
 */
export class AIController {
  private host: AIHost
  private state: AIState = IDLE_AI_STATE
  private listeners = new Set<() => void>()
  private runId = 0
  private abort: AbortController | null = null
  private target: EditorBookmark | null = null
  private request: AIRequest | null = null
  private definition: AIActionDefinition | null = null
  /** What the person typed into the prompt box, to show with the answer. */
  private typed: string | undefined
  private buffer = ""
  private flushTimer: ReturnType<typeof setTimeout> | null = null

  constructor(host: AIHost) {
    this.host = host
  }

  subscribe = (listener: () => void) => {
    this.listeners.add(listener)
    return () => {
      this.listeners.delete(listener)
    }
  }

  getState = () => this.state

  /** The AI commands on offer, `ask` first when custom prompts are allowed. */
  definitions(): AIActionDefinition[] {
    const config = this.host.getConfig()
    if (!config?.enabled) return []
    const actions = config.actions ?? DEFAULT_AI_ACTIONS
    return config.allowCustomPrompts === false ? actions : [ASK_AI, ...actions]
  }

  find(actionId: string) {
    const id = actionId.replace(/^ai\./, "")
    return this.definitions().find((definition) => definition.id === id)
  }

  /**
   * Opens the prompt box for "Ask AI…" (or another action that asks for an
   * instruction), bookmarking the selection then, so the answer lands there
   * even though focus moves to the box.
   */
  openPrompt(range?: EditorRange, actionId: string = ASK_AI.id) {
    const editor = this.host.getEditor()
    const definition = this.find(actionId)
    if (!editor || !definition) return
    this.reset()
    const selection = range ?? this.host.controller.getSelection()
    this.target = createBookmark(editor, selection, { highlight: true })
    this.setState({
      ...IDLE_AI_STATE,
      status: "prompt",
      action: definition,
      hasSelection: selection.from !== selection.to,
    })
  }

  /** Runs the action the prompt box is open for, with what was typed. */
  async submitPrompt(instruction: string) {
    const { status, action } = this.state
    if (status !== "prompt" || !action || !instruction.trim()) return
    await this.start(action.id, { instruction })
  }

  /**
   * Runs `actionId` (`rewrite` or `ai.rewrite`) on `range`, or on the
   * selection. Resolves once the answer is in (or the run ends otherwise).
   */
  async start(
    actionId: string,
    options: { instruction?: string; range?: EditorRange } = {}
  ) {
    const { controller, onError } = this.host
    const editor = this.host.getEditor()
    const definition = this.find(actionId)
    if (!editor || !definition) {
      onError({
        code: "unknown-action",
        message: `There's no AI action "${actionId}".`,
        actionId,
      })
      return
    }

    // From the prompt box, act on what was selected when it opened.
    const prompted =
      this.state.status === "prompt" ? (this.target?.resolve() ?? null) : null
    const range = options.range ?? prompted
    if (range) controller.setSelection(range)
    const selection = controller.getSelection()
    if (definition.requiresSelection && selection.empty) {
      onError({
        code: "action-failed",
        message: `"${definition.label}" needs some selected text.`,
        actionId: `ai.${definition.id}`,
      })
      return
    }

    this.reset()
    this.target = createBookmark(editor, selection, { highlight: true })
    this.definition = definition
    const config = this.host.getConfig()
    const context =
      typeof config?.context === "function"
        ? config.context(definition.id)
        : config?.context
    // What the person typed follows the action's own prompt.
    const typed = options.instruction?.trim() || undefined
    this.typed = typed
    const instruction =
      typed && definition.prompt
        ? `${definition.prompt}\n\n${typed}`
        : (typed ?? definition.prompt)
    this.request = {
      actionId: definition.id,
      ...(instruction && { instruction }),
      selectedText: selection.text,
      selectedMarkdown: controller.getSelectedMarkdown(),
      selection: { from: selection.from, to: selection.to },
      documentMarkdown: controller.getMarkdown(),
      ...(context && { context }),
    }
    await this.run()
  }

  /** Asks again with the same request; the target stays bookmarked. */
  async regenerate() {
    if (!this.request || this.state.status === "running") return
    await this.run()
  }

  /**
   * Writes the answer: where the action said, or `target`. `cursor` puts it
   * at the selection as it is now (the way out of a conflict). Returns
   * whether the document changed.
   */
  accept(target?: AIResultMode | "cursor"): boolean {
    const { status, markdown, mode, hasSelection } = this.state
    if (status !== "ready" && status !== "conflict") return false
    let where = target ?? mode
    if (where === "preview") where = hasSelection ? "replace" : "insert"
    const { controller } = this.host

    let applied: boolean
    if (where === "append") applied = controller.appendMarkdown(markdown)
    else if (where === "cursor") applied = controller.insertMarkdown(markdown)
    else {
      const range = this.target?.resolve() ?? null
      if (!range) {
        this.setState({ ...this.state, status: "conflict" })
        this.host.onError({
          code: "ai-target-changed",
          message:
            "The text this was for changed while the AI worked. Choose where the result goes.",
          actionId: this.definition ? `ai.${this.definition.id}` : undefined,
        })
        return false
      }
      applied =
        where === "replace"
          ? controller.replaceRange(range, markdown)
          : this.insertAfter(range, markdown)
    }
    if (applied) this.reset()
    return applied
  }

  /** Drops the answer; the document stays as it is. */
  reject() {
    this.reset()
  }

  /** Stops a running request and closes the flow. */
  cancel() {
    this.reset()
  }

  dispose() {
    this.reset()
    this.listeners.clear()
  }

  private async run() {
    const config = this.host.getConfig()
    const request = this.request
    if (!config || !request) return
    const runId = (this.runId += 1)
    this.abort?.abort()
    const abort = new AbortController()
    this.abort = abort
    this.buffer = ""
    this.clearFlush()
    const definition = this.definition
    const mode: AIResultMode =
      definition?.resultMode ??
      (request.selection.from === request.selection.to ? "insert" : "replace")
    this.setState({
      status: "running",
      action: definition,
      instruction: this.typed,
      markdown: "",
      mode,
      hasSelection: request.selection.from !== request.selection.to,
    })

    try {
      const result: AIResult | AsyncIterable<AIStreamEvent> =
        await config.execute(request, { signal: abort.signal })
      if (runId !== this.runId) return

      let markdown: string
      let resultMode = mode
      if (isAsyncIterable<AIStreamEvent>(result)) {
        let final: string | undefined
        for await (const event of result) {
          // Leaving the loop also closes the host's stream.
          if (runId !== this.runId) return
          if (event.type === "delta") {
            this.buffer += event.text
            this.scheduleFlush(runId)
          } else if (event.type === "complete") {
            final = event.markdown ?? this.buffer
            break
          } else if (event.type === "error") {
            throw new Error(event.message || "The AI request failed.")
          }
        }
        if (runId !== this.runId) return
        markdown = final ?? this.buffer
      } else {
        markdown = result?.markdown ?? ""
        resultMode = result?.mode ?? mode
      }
      this.clearFlush()
      if (!markdown.trim()) throw new Error("The AI didn't return anything.")

      this.setState({
        ...this.state,
        status: "ready",
        markdown,
        mode: resultMode,
      })
      if (config.requireApproval === false && resultMode !== "preview") {
        this.accept()
      }
    } catch (cause) {
      if (runId !== this.runId || abort.signal.aborted) return
      this.clearFlush()
      const message =
        cause instanceof Error && cause.message
          ? cause.message
          : "The AI request failed."
      this.setState({ ...this.state, status: "error", error: message })
      this.host.onError({
        code: "ai-failed",
        message,
        actionId: definition ? `ai.${definition.id}` : undefined,
        cause,
      })
    } finally {
      if (this.abort === abort) this.abort = null
    }
  }

  /**
   * After the selection: below the block it ends in, so the answer becomes
   * its own paragraphs; at a caret, right there.
   */
  private insertAfter(range: EditorRange, markdown: string) {
    const { controller } = this.host
    const editor = this.host.getEditor()
    if (!editor || range.from === range.to) {
      return controller.replaceRange(range, markdown)
    }
    const $to = editor.state.doc.resolve(range.to)
    const at = $to.parent.isTextblock ? $to.after() : range.to
    return controller.replaceRange({ from: at, to: at }, markdown)
  }

  private reset() {
    this.runId += 1
    this.abort?.abort()
    this.abort = null
    this.clearFlush()
    this.target?.release()
    this.target = null
    this.request = null
    this.definition = null
    this.typed = undefined
    this.buffer = ""
    if (this.state !== IDLE_AI_STATE) this.setState(IDLE_AI_STATE)
  }

  private scheduleFlush(runId: number) {
    if (this.flushTimer) return
    this.flushTimer = setTimeout(() => {
      this.flushTimer = null
      if (runId === this.runId && this.state.status === "running") {
        this.setState({ ...this.state, markdown: this.buffer })
      }
    }, FLUSH_MS)
  }

  private clearFlush() {
    if (this.flushTimer) clearTimeout(this.flushTimer)
    this.flushTimer = null
  }

  private setState(state: AIState) {
    this.state = state
    for (const listener of this.listeners) listener()
  }
}

import type { EditorRange } from "../types.ts"

/**
 * Where a finished AI result goes: `replace` swaps the text the action ran
 * on, `insert` adds it after that text (or at the caret), `append` adds it at
 * the end of the document, and `preview` only shows it, so the person picks.
 */
export type AIResultMode = "insert" | "replace" | "append" | "preview"

/** One AI command the editor offers, as `ai.<id>` in menus and toolbars. */
export interface AIActionDefinition {
  id: string
  label: string
  /** Sent to `execute` as `instruction`; the host turns it into a prompt. */
  prompt?: string
  /** Only offered while text is selected. */
  requiresSelection?: boolean
  resultMode?: AIResultMode
  /** Shown in the `/` menu and as a tooltip. */
  description?: string
  /**
   * Opens the prompt box first: what the person types is sent as
   * `instruction` (after `prompt`, when there's one), like "Ask AI…".
   */
  askInstruction?: boolean
  /** The prompt box's placeholder, for an action that asks. */
  placeholder?: string
}

/** What the editor sends the host's `execute` callback. Plain JSON. */
export interface AIRequest {
  actionId: string
  instruction?: string
  selectedText: string
  /** Markdown of the selection, so formatting survives the round trip. */
  selectedMarkdown: string
  selection: EditorRange
  documentMarkdown: string
  context?: Record<string, unknown>
}

export interface AIResult {
  markdown: string
  mode?: AIResultMode
}

export type AIStreamEvent =
  | { type: "delta"; text: string }
  | { type: "complete"; markdown?: string }
  | { type: "error"; message: string }

export interface AIExecuteOptions {
  /** Aborted when the person cancels or the editor unmounts. */
  signal: AbortSignal
}

export interface EditorAIConfig {
  enabled: boolean
  /** The AI commands; without them the editor offers rewrite, fix, summarize, expand and continue. */
  actions?: AIActionDefinition[]
  /** Runs a request: return the whole result, or stream events. */
  execute: (
    request: AIRequest,
    options: AIExecuteOptions
  ) =>
    | Promise<AIResult | AsyncIterable<AIStreamEvent>>
    | AsyncIterable<AIStreamEvent>
  /** Show results for Accept / Reject before they change the document. Default true. */
  requireApproval?: boolean
  /** Offer "Ask AI…", where the person types their own instruction. Default true. */
  allowCustomPrompts?: boolean
  /** Extra data for the host, sent as `request.context`. */
  context?:
    | Record<string, unknown>
    | ((actionId: string) => Record<string, unknown> | undefined)
}

/**
 * Where the AI flow is: `prompt` while the person types an instruction,
 * `running` while the host works (text streams into `markdown`), `ready`
 * with a result waiting for approval, `conflict` when the text it was meant
 * for changed meanwhile, `error` when it failed.
 */
export type AIStatus =
  "idle" | "prompt" | "running" | "ready" | "conflict" | "error"

export interface AIState {
  status: AIStatus
  /** The action that ran, or null when idle. */
  action: AIActionDefinition | null
  /** The instruction typed into "Ask AI…", if any. */
  instruction?: string
  /** The result so far (streaming) or in full. */
  markdown: string
  mode: AIResultMode
  /** Whether the run had a selection to replace. */
  hasSelection: boolean
  error?: string
}

export const IDLE_AI_STATE: AIState = {
  status: "idle",
  action: null,
  markdown: "",
  mode: "insert",
  hasSelection: false,
}

import * as React from "react"
import {
  ArrowDown02Icon,
  ArrowUp02Icon,
  Copy01Icon,
  Delete02Icon,
} from "@hugeicons/core-free-icons"
import { DragHandle } from "@tiptap/extension-drag-handle-react"
import type { Node as PMNode } from "@tiptap/pm/model"
import { TextSelection } from "@tiptap/pm/state"
import type { Editor } from "@tiptap/react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Icon } from "../icon"
import { ActionIcon } from "./controls"
import { useRichTextEditorContext } from "./context"
import { createActionContext } from "./core/action-registry"

// Blocks "Turn into" can convert: text blocks, lists and quotes.
const CONVERTIBLE = new Set([
  "paragraph",
  "heading",
  "codeBlock",
  "blockquote",
  "bulletList",
  "orderedList",
  "taskList",
])

// The registry's actions "Turn into" offers, when their features are on.
const TURN_INTO = [
  "paragraph",
  "heading1",
  "heading2",
  "heading3",
  "bulletList",
  "orderedList",
  "taskList",
  "blockquote",
  "codeBlock",
]

type Target = { node: PMNode | null; pos: number }

/**
 * The handle beside the hovered block: `+` adds a block below through the
 * `/` menu; the grip drags the block, and clicking it opens a menu to turn
 * it into another kind, move, duplicate or delete it.
 */
export function BlockHandle({ editor }: { editor: Editor }) {
  const { registry, controller } = useRichTextEditorContext()
  const target = React.useRef<Target>({ node: null, pos: -1 })
  const [menuOpen, setMenuOpen] = React.useState(false)
  const [menuTarget, setMenuTarget] = React.useState<Target | null>(null)

  const openMenu = (open: boolean) => {
    setMenuOpen(open)
    setMenuTarget(open ? target.current : null)
    // Keep the handle on this block while its menu is open.
    if (open) editor.commands.lockDragHandle()
    else editor.commands.unlockDragHandle()
  }

  const current = () => {
    const { node, pos } = target.current
    return node && pos >= 0 ? { node, pos } : null
  }

  const addBelow = () => {
    const block = current()
    if (!block) return
    const { node, pos } = block
    if (node.type.name === "paragraph" && node.content.size === 0) {
      editor
        .chain()
        .focus()
        .setTextSelection(pos + 1)
        .insertContent("/")
        .run()
      return
    }
    const after = pos + node.nodeSize
    editor
      .chain()
      .focus()
      .insertContentAt(after, {
        type: "paragraph",
        content: [{ type: "text", text: "/" }],
      })
      .setTextSelection(after + 2)
      .run()
  }

  /** Selects the whole block so a command converts all of it. */
  const selectBlock = (node: PMNode, pos: number) =>
    editor
      .chain()
      .focus()
      .command(({ tr }) => {
        tr.setSelection(
          TextSelection.between(
            tr.doc.resolve(pos + 1),
            tr.doc.resolve(pos + node.nodeSize - 1)
          )
        )
        return true
      })
      .run()

  const turnInto = (id: string) => {
    const block = current()
    if (!block) return
    selectBlock(block.node, block.pos)
    void registry.run(id, createActionContext(controller, "api"))
  }

  const move = (direction: -1 | 1) => {
    const block = current()
    if (!block) return
    const { node, pos } = block
    editor
      .chain()
      .focus()
      .command(({ tr }) => {
        const $pos = tr.doc.resolve(pos)
        const index = $pos.index()
        const sibling = $pos.parent.maybeChild(index + direction)
        if (!sibling) return false
        tr.delete(pos, pos + node.nodeSize)
        const insertAt =
          direction === -1 ? pos - sibling.nodeSize : pos + sibling.nodeSize
        tr.insert(insertAt, node)
        tr.setSelection(TextSelection.near(tr.doc.resolve(insertAt + 1)))
        tr.scrollIntoView()
        return true
      })
      .run()
  }

  const duplicate = () => {
    const block = current()
    if (!block) return
    editor
      .chain()
      .focus()
      .insertContentAt(block.pos + block.node.nodeSize, block.node.toJSON())
      .run()
  }

  const remove = () => {
    const block = current()
    if (!block) return
    editor
      .chain()
      .focus()
      .deleteRange({ from: block.pos, to: block.pos + block.node.nodeSize })
      .run()
  }

  const turnIntoActions = TURN_INTO.flatMap((id) => {
    const action = registry.get(id)
    return action ? [action] : []
  })
  const menuNode = menuTarget?.node ?? null
  const index =
    menuTarget && menuTarget.pos >= 0
      ? editor.state.doc.resolve(menuTarget.pos).index()
      : 0
  const siblings = editor.state.doc.childCount

  return (
    <DragHandle
      editor={editor}
      className="drag-handle z-20"
      onNodeChange={({ node, pos }) => {
        target.current = { node, pos }
      }}
    >
      <div className="flex items-center gap-px pr-1.5">
        <Button
          type="button"
          variant="ghost"
          size="icon-xs"
          aria-label="Add a block below"
          onClick={addBelow}
          className="text-subtle hover:text-foreground"
        >
          <Icon icon="plus" />
        </Button>
        <div className="relative">
          <Button
            type="button"
            variant="ghost"
            size="icon-xs"
            aria-label="Drag to move, or click for block options"
            aria-haspopup="menu"
            aria-expanded={menuOpen}
            onClick={() => openMenu(true)}
            className="cursor-grab text-subtle hover:text-foreground active:cursor-grabbing"
          >
            <Icon icon="grip" />
          </Button>
          {/* Anchors the menu, which opens on click rather than on the
              mousedown that starts a drag. */}
          <DropdownMenu open={menuOpen} onOpenChange={openMenu}>
            <DropdownMenuTrigger
              nativeButton={false}
              render={
                <span
                  aria-hidden="true"
                  tabIndex={-1}
                  className="pointer-events-none absolute inset-0"
                />
              }
            />
            <DropdownMenuContent
              side="bottom"
              align="start"
              className="min-w-52"
              finalFocus={() => editor.view.dom as HTMLElement}
            >
              {menuNode && CONVERTIBLE.has(menuNode.type.name) && (
                <>
                  <DropdownMenuSub>
                    <DropdownMenuSubTrigger>
                      <Icon icon="refresh" />
                      Turn into
                    </DropdownMenuSubTrigger>
                    <DropdownMenuSubContent className="min-w-48">
                      {turnIntoActions.map((action) => (
                        <DropdownMenuItem
                          key={action.id}
                          onClick={() => turnInto(action.id)}
                        >
                          <ActionIcon icon={action.icon} />
                          {action.label}
                        </DropdownMenuItem>
                      ))}
                    </DropdownMenuSubContent>
                  </DropdownMenuSub>
                  <DropdownMenuSeparator />
                </>
              )}
              <DropdownMenuGroup>
                <DropdownMenuItem
                  disabled={index === 0}
                  onClick={() => move(-1)}
                >
                  <Icon icon={ArrowUp02Icon} />
                  Move up
                </DropdownMenuItem>
                <DropdownMenuItem
                  disabled={index >= siblings - 1}
                  onClick={() => move(1)}
                >
                  <Icon icon={ArrowDown02Icon} />
                  Move down
                </DropdownMenuItem>
                <DropdownMenuItem onClick={duplicate}>
                  <Icon icon={Copy01Icon} />
                  Duplicate
                </DropdownMenuItem>
              </DropdownMenuGroup>
              <DropdownMenuSeparator />
              <DropdownMenuItem variant="destructive" onClick={remove}>
                <Icon icon={Delete02Icon} />
                Delete
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>
    </DragHandle>
  )
}

import * as React from "react"
import {
  Delete02Icon,
  DeleteColumnIcon,
  DeleteRowIcon,
  InsertColumnLeftIcon,
  InsertColumnRightIcon,
  InsertRowDownIcon,
  InsertRowUpIcon,
  SparklesIcon,
  Unlink02Icon,
} from "@hugeicons/core-free-icons"
import { NodeSelection } from "@tiptap/pm/state"
import { CellSelection } from "@tiptap/pm/tables"
import { useEditorState, type Editor } from "@tiptap/react"
import { BubbleMenu } from "@tiptap/react/menus"
import { cn } from "cn"

import {
  DropdownMenu,
  DropdownMenuContent,
} from "@/components/ui/dropdown-menu"
import { Icon } from "../icon"
import {
  ToolbarAction,
  ToolbarMenuTrigger,
  ToolbarSeparator,
  ToolbarToggle,
} from "./controls"
import {
  useEditorActions,
  useRichTextEditorContext,
  useRunAction,
} from "./context"
import { isAlive } from "./core/lifecycle"
import { MenuEntries } from "./menu-items"
import { DEFAULT_BUBBLE_ITEMS, tidySeparators } from "./menu-model"
import type { EditorUiHandlers, ToolbarItem } from "./types"

const MENU =
  "z-30 flex items-center gap-0.5 rounded-(--radius-band) border border-border bg-popover p-1 text-popover-foreground shadow-(--shadow-float)"

type MenuProps = {
  editor: Editor
  ui: () => EditorUiHandlers
  scrollTarget: HTMLElement
}

const hasNode = (editor: Editor, name: string) =>
  Boolean(editor.schema.nodes[name])

/**
 * Formatting for a text selection, drawn from `items` through the action
 * registry; `"ai"` opens the AI actions.
 */
function TextMenu({
  editor,
  scrollTarget,
  items,
  hidden,
}: Omit<MenuProps, "ui"> & { items: ToolbarItem[]; hidden: boolean }) {
  const { registry } = useRichTextEditorContext()
  const ids = items.filter(
    (item): item is string =>
      typeof item === "string" && item !== "separator" && item !== "ai"
  )
  const resolved = useEditorActions(ids, "bubbleMenu")
  const byId = new Map(resolved.map((entry) => [entry.id, entry]))
  const run = useRunAction("bubbleMenu")
  const aiIds = registry
    .list()
    .filter((action) => action.id.startsWith("ai."))
    .map((action) => action.id)

  type Entry = { separator: boolean; node: React.ReactNode }
  const entries = tidySeparators(
    items.flatMap((item): Entry[] => {
      if (item === "separator") return [{ separator: true, node: null }]
      if (item === "ai") {
        if (!aiIds.length) return []
        return [
          {
            separator: false,
            node: (
              <DropdownMenu key="ai">
                <ToolbarMenuTrigger icon={SparklesIcon} label="AI" value="AI" />
                <DropdownMenuContent
                  finalFocus={() => editor.view.dom as HTMLElement}
                  className="min-w-56"
                >
                  <MenuEntries
                    items={aiIds}
                    kind="dropdown"
                    source="bubbleMenu"
                    onRun={run}
                  />
                </DropdownMenuContent>
              </DropdownMenu>
            ),
          },
        ]
      }
      if (typeof item !== "string") return []
      const entry = byId.get(item)
      if (!entry?.state.visible) return []
      const { action, state } = entry
      return [
        {
          separator: false,
          node: action.isActive ? (
            <ToolbarToggle
              key={item}
              icon={action.icon}
              label={action.label}
              shortcut={action.shortcut}
              pressed={state.active}
              disabled={!state.enabled}
              onPressedChange={() => run(action.id)}
            />
          ) : (
            <ToolbarAction
              key={item}
              icon={action.icon}
              label={action.label}
              shortcut={action.shortcut}
              disabled={!state.enabled}
              busy={state.running}
              onClick={() => run(action.id)}
            />
          ),
        },
      ]
    })
  )

  return (
    <BubbleMenu
      editor={editor}
      pluginKey="richTextSelectionMenu"
      className={cn(MENU, hidden && "hidden")}
      options={{ placement: "top", offset: 8, scrollTarget }}
      shouldShow={({ editor, state, from, to, view }) => {
        if (!editor.isEditable || from === to || !view.hasFocus()) return false
        const { selection } = state
        if (selection instanceof NodeSelection) return false
        if (selection instanceof CellSelection) return false
        if (editor.isActive("codeBlock")) return false
        return state.doc.textBetween(from, to, " ").trim().length > 0
      }}
    >
      {entries.map((entry, index) =>
        entry.separator ? <ToolbarSeparator key={index} /> : entry.node
      )}
    </BubbleMenu>
  )
}

/** Shown with the caret in a link: where it goes, edit, copy, remove. */
function LinkMenu({ editor, ui, scrollTarget }: MenuProps) {
  const href = useEditorState({
    editor,
    selector: ({ editor }) =>
      (editor.getAttributes("link").href as string | undefined) ?? "",
  })
  return (
    <BubbleMenu
      editor={editor}
      pluginKey="richTextLinkMenu"
      className={cn(MENU, "max-w-sm")}
      options={{ placement: "bottom-start", offset: 6, scrollTarget }}
      shouldShow={({ editor, from, to, view }) =>
        editor.isEditable &&
        from === to &&
        view.hasFocus() &&
        editor.isActive("link")
      }
    >
      <a
        href={href}
        target="_blank"
        rel="noopener noreferrer nofollow"
        className="flex min-w-0 items-center gap-1.5 rounded-(--radius-item) px-1.5 py-1 text-xs text-foreground hover:bg-muted"
      >
        <Icon
          icon="external"
          size={14}
          className="shrink-0 text-muted-foreground"
        />
        <span className="truncate">{href}</span>
      </a>
      <ToolbarSeparator />
      <ToolbarAction
        icon="settings"
        label="Edit link"
        shortcut="Mod-k"
        onClick={() => ui().openDialog({ kind: "link" })}
      />
      <ToolbarAction
        icon="copy"
        label="Copy link"
        onClick={() => void navigator.clipboard.writeText(href)}
      />
      <ToolbarAction
        icon={Unlink02Icon}
        label="Remove link"
        onClick={() =>
          editor.chain().focus().extendMarkRange("link").unsetLink().run()
        }
      />
    </BubbleMenu>
  )
}

/** The table under the caret, found in the DOM for positioning the menu. */
function tableElement(editor: Editor) {
  const { node } = editor.view.domAtPos(editor.state.selection.from)
  const element = node instanceof Element ? node : node.parentElement
  return element?.closest(".tableWrapper") ?? element?.closest("table") ?? null
}

/**
 * Rows and columns of the table under the caret. GFM tables have one header
 * row and no merged cells, so those are all the menu offers.
 */
function TableMenu({ editor, scrollTarget }: MenuProps) {
  const can = useEditorState({
    editor,
    selector: ({ editor }) =>
      isAlive(editor)
        ? {
            deleteRow: editor.can().deleteRow(),
            deleteColumn: editor.can().deleteColumn(),
          }
        : { deleteRow: false, deleteColumn: false },
  })
  const chain = () => editor.chain().focus()
  return (
    <BubbleMenu
      editor={editor}
      pluginKey="richTextTableMenu"
      className={MENU}
      options={{ placement: "top-start", offset: 6, scrollTarget }}
      getReferencedVirtualElement={() => {
        const table = tableElement(editor)
        return table
          ? { getBoundingClientRect: () => table.getBoundingClientRect() }
          : null
      }}
      // Out of the way of the selection menu while text is selected.
      shouldShow={({ editor, view, state, from, to }) =>
        editor.isEditable &&
        view.hasFocus() &&
        editor.isActive("table") &&
        (from === to || state.selection instanceof CellSelection)
      }
    >
      <ToolbarAction
        icon={InsertRowUpIcon}
        label="Row above"
        onClick={() => chain().addRowBefore().run()}
      />
      <ToolbarAction
        icon={InsertRowDownIcon}
        label="Row below"
        onClick={() => chain().addRowAfter().run()}
      />
      <ToolbarAction
        icon={DeleteRowIcon}
        label="Delete row"
        disabled={!can.deleteRow}
        onClick={() => chain().deleteRow().run()}
      />
      <ToolbarSeparator />
      <ToolbarAction
        icon={InsertColumnLeftIcon}
        label="Column left"
        onClick={() => chain().addColumnBefore().run()}
      />
      <ToolbarAction
        icon={InsertColumnRightIcon}
        label="Column right"
        onClick={() => chain().addColumnAfter().run()}
      />
      <ToolbarAction
        icon={DeleteColumnIcon}
        label="Delete column"
        disabled={!can.deleteColumn}
        onClick={() => chain().deleteColumn().run()}
      />
      <ToolbarSeparator />
      <ToolbarAction
        icon={Delete02Icon}
        label="Delete table"
        onClick={() => chain().deleteTable().run()}
        className="hover:bg-destructive/10 hover:text-destructive"
      />
    </BubbleMenu>
  )
}

/** A selected image: alt text and source, open, delete. */
function ImageMenu({ editor, ui, scrollTarget }: MenuProps) {
  const src = useEditorState({
    editor,
    selector: ({ editor }) =>
      (editor.getAttributes("image").src as string | undefined) ?? "",
  })
  return (
    <BubbleMenu
      editor={editor}
      pluginKey="richTextImageMenu"
      className={MENU}
      options={{ placement: "top", offset: 8, scrollTarget }}
      shouldShow={({ editor, state }) =>
        editor.isEditable &&
        state.selection instanceof NodeSelection &&
        state.selection.node.type.name === "image"
      }
    >
      <ToolbarAction
        icon="settings"
        label="Alt text and source"
        onClick={() =>
          ui().openDialog({
            kind: "image",
            pos: editor.state.selection.from,
          })
        }
      />
      {!src.startsWith("data:") && (
        <ToolbarAction
          icon="external"
          label="Open image"
          onClick={() => window.open(src, "_blank", "noopener,noreferrer")}
        />
      )}
      <ToolbarSeparator />
      <ToolbarAction
        icon={Delete02Icon}
        label="Delete image"
        onClick={() => editor.chain().focus().deleteSelection().run()}
        className="hover:bg-destructive/10 hover:text-destructive"
      />
    </BubbleMenu>
  )
}

/** Every contextual menu the editor shows, for the features it has. */
export function EditorBubbleMenu({
  scrollTarget,
  items = DEFAULT_BUBBLE_ITEMS,
}: {
  scrollTarget: HTMLElement
  /** What the selection menu shows. */
  items?: ToolbarItem[]
}) {
  const { editor, ui, ai } = useRichTextEditorContext()
  // While the AI panel is open, focus is there: the selection menu would
  // float over the text with nothing to act on. Hidden, not unmounted: its
  // AI menu may still be closing, and unmounting it would send focus back
  // to the text instead of the prompt box.
  const aiOpen = React.useSyncExternalStore(
    ai.subscribe,
    () => ai.getState().status !== "idle"
  )
  const props = { editor, ui, scrollTarget }
  return (
    <>
      <TextMenu
        editor={editor}
        scrollTarget={scrollTarget}
        items={items}
        hidden={aiOpen}
      />
      {editor.schema.marks.link && <LinkMenu {...props} />}
      {hasNode(editor, "table") && <TableMenu {...props} />}
      {hasNode(editor, "image") && <ImageMenu {...props} />}
    </>
  )
}

import * as React from "react"
import { cn } from "cn"

import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuTrigger,
} from "@/components/ui/context-menu"
import { useRichTextEditorContext } from "./context"
import { createActionContext } from "./core/action-registry"
import { MenuEntries } from "./menu-items"
import {
  defaultContextMenuItems,
  expandAIMenu,
  menuActionIds,
} from "./menu-model"
import type { EditorActionContext, MenuItem } from "./types"

/**
 * The right-click menu over the text. It snapshots the selection as it
 * opens; choosing an entry puts that selection back and runs the action with
 * the snapshot, so focus moving into the menu never changes what it acts on.
 * Keyboard users open it with the context-menu key or Shift+F10.
 */
export function EditorContextMenu({
  items,
  className,
  children,
}: {
  /** Defaults to clipboard, formatting, the app's actions and AI. */
  items?: MenuItem[]
  className?: string
  children: React.ReactNode
}) {
  const { editor, controller, registry } = useRichTextEditorContext()
  const [snapshot, setSnapshot] = React.useState<EditorActionContext | null>(
    null
  )

  const actions = registry.list()
  const aiIds = actions.filter((a) => a.id.startsWith("ai.")).map((a) => a.id)
  const defaults = defaultContextMenuItems([])
  const builtInIds = new Set(menuActionIds(defaults))
  // The app's own actions get a place in the default menu.
  const customIds = actions
    .filter(
      (action) =>
        !registry.isBuiltIn(action.id) &&
        !action.id.startsWith("ai.") &&
        !builtInIds.has(action.id)
    )
    .map((action) => action.id)
  const entries = expandAIMenu(
    items ?? defaultContextMenuItems(customIds),
    aiIds
  )

  const run = (id: string) => {
    if (!snapshot) return
    controller.setSelection(snapshot.selection)
    void registry.run(id, snapshot)
  }

  return (
    <ContextMenu
      onOpenChange={(open) => {
        setSnapshot(
          open ? createActionContext(controller, "contextMenu") : null
        )
      }}
    >
      <ContextMenuTrigger className={cn("select-text", className)}>
        {children}
      </ContextMenuTrigger>
      <ContextMenuContent
        finalFocus={() => editor.view.dom as HTMLElement}
        className="min-w-52"
      >
        {snapshot && (
          <MenuEntries
            items={entries}
            kind="context"
            source="contextMenu"
            onRun={run}
          />
        )}
      </ContextMenuContent>
    </ContextMenu>
  )
}

import * as React from "react"
import { useEditorState, type Editor } from "@tiptap/react"

import type { AIController } from "./ai/ai-controller"
import {
  createActionContext,
  type ActionRegistry,
  type ActionState,
} from "./core/action-registry"
import { isAlive } from "./core/lifecycle"
import type {
  ActionSource,
  EditorAction,
  EditorController,
  EditorUiHandlers,
  ResolvedEditorFeatures,
  UrlPolicy,
} from "./types"

/** Everything an editor's UI pieces share. */
export interface RichTextEditorContextValue {
  editor: Editor
  controller: EditorController
  registry: ActionRegistry
  ai: AIController
  features: ResolvedEditorFeatures
  ui: () => EditorUiHandlers
  /** The link and image URL policy in force. */
  urlPolicy: () => UrlPolicy
}

export const RichTextEditorContext =
  React.createContext<RichTextEditorContextValue | null>(null)

/** The surrounding editor, for toolbars and menus rendered inside it. */
export function useRichTextEditorContext() {
  const context = React.useContext(RichTextEditorContext)
  if (!context) {
    throw new Error(
      "useRichTextEditorContext needs a RichTextEditor (or RichTextEditorProvider) around it."
    )
  }
  return context
}

export interface ResolvedAction {
  /** The id as asked for (an alias like `code` stays `code`). */
  id: string
  action: EditorAction
  state: ActionState
}

const HIDDEN: ActionState = {
  visible: false,
  enabled: false,
  active: false,
  running: false,
}

/**
 * The actions behind `ids` with their state at the current selection
 * (visible, enabled, pressed, running). Re-renders when the selection,
 * document or registry changes; unknown ids are left out.
 */
export function useEditorActions(
  ids: string[],
  source: ActionSource = "toolbar"
): ResolvedAction[] {
  const { editor, controller, registry } = useRichTextEditorContext()
  // A new or replaced action, or one starting or finishing, re-renders.
  React.useSyncExternalStore(registry.subscribe, registry.getVersion)
  const key = ids.join("\u0000")
  const encoded = useEditorState({
    editor,
    // The controller reads the current editor; the snapshot's can be one
    // Tiptap already replaced (StrictMode builds the first one twice).
    selector: () => {
      if (!isAlive(controller.getTiptapEditor())) return ""
      const context = createActionContext(controller, source)
      return key
        .split("\u0000")
        .map((id) => {
          const state = registry.state(id, context)
          return [state.visible, state.enabled, state.active, state.running]
            .map(Number)
            .join("")
        })
        .join(",")
    },
  })
  const states = encoded ? encoded.split(",") : []

  return ids.flatMap((id, index) => {
    const action = registry.get(id)
    if (!action) return []
    const bits = states[index]
    const state: ActionState = bits
      ? {
          visible: bits[0] === "1",
          enabled: bits[1] === "1",
          active: bits[2] === "1",
          running: bits[3] === "1",
        }
      : HIDDEN
    return [{ id, action, state }]
  })
}

/** Runs an action by id with a fresh snapshot of the selection. */
export function useRunAction(source: ActionSource = "toolbar") {
  const { controller, registry } = useRichTextEditorContext()
  return React.useCallback(
    (id: string) =>
      void registry.run(id, createActionContext(controller, source)),
    [controller, registry, source]
  )
}

import * as React from "react"
import { cn } from "cn"

import { Button } from "@/components/ui/button"
import { DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { Kbd } from "@/components/ui/kbd"
import { PopoverTrigger } from "@/components/ui/popover"
import { Separator } from "@/components/ui/separator"
import { Spinner } from "@/components/ui/spinner"
import { Toggle } from "@/components/ui/toggle"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { Icon } from "../icon"
import { iconNames, type IconProp } from "../icons"
import { formatShortcut } from "./shortcuts"
import type { EditorAction } from "./types"

const NAMES = new Set<string>(iconNames)

/** Whether `icon` is a Hugeicons glyph (an array of SVG element tuples). */
function isGlyph(icon: unknown): icon is IconProp {
  return (
    Array.isArray(icon) &&
    Array.isArray(icon[0]) &&
    typeof icon[0][0] === "string"
  )
}

/**
 * An action's icon, which may be a React node, a Forge icon name or a
 * Hugeicons glyph. Strings that aren't icon names render as text.
 */
export function ActionIcon({
  icon,
  size,
}: {
  icon: EditorAction["icon"]
  size?: number
}) {
  if (icon === undefined || icon === null || icon === false) return null
  if (typeof icon === "string" && NAMES.has(icon)) {
    return <Icon icon={icon as IconProp} size={size} />
  }
  if (isGlyph(icon)) return <Icon icon={icon} size={size} />
  return <>{icon as React.ReactNode}</>
}

function Hint({ label, shortcut }: { label: string; shortcut?: string }) {
  return (
    <TooltipContent side="bottom">
      {label}
      {shortcut && <Kbd>{formatShortcut(shortcut)}</Kbd>}
    </TooltipContent>
  )
}

/** An on/off formatting button (bold, bulleted list, …) with its shortcut. */
export function ToolbarToggle({
  icon,
  label,
  shortcut,
  pressed,
  disabled,
  onPressedChange,
}: {
  icon: EditorAction["icon"]
  label: string
  shortcut?: string
  pressed: boolean
  disabled?: boolean
  onPressedChange: () => void
}) {
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Toggle
            size="sm"
            aria-label={label}
            pressed={pressed}
            disabled={disabled}
            onPressedChange={onPressedChange}
            className="min-w-7 px-1.5 text-muted-foreground aria-pressed:text-foreground"
          />
        }
      >
        <ActionIcon icon={icon} />
      </TooltipTrigger>
      <Hint label={label} shortcut={shortcut} />
    </Tooltip>
  )
}

/** A one-shot action (undo, clear formatting, …). */
export function ToolbarAction({
  icon,
  label,
  shortcut,
  disabled,
  busy,
  onClick,
  className,
}: {
  icon: EditorAction["icon"]
  label: string
  shortcut?: string
  disabled?: boolean
  /** Shows a spinner while the action runs. */
  busy?: boolean
  onClick: () => void
  className?: string
}) {
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button
            type="button"
            variant="ghost"
            size="icon-sm"
            aria-label={label}
            aria-busy={busy || undefined}
            disabled={disabled}
            onClick={onClick}
            className={cn("text-muted-foreground", className)}
          />
        }
      >
        {busy ? <Spinner /> : <ActionIcon icon={icon} />}
      </TooltipTrigger>
      <Hint label={label} shortcut={shortcut} />
    </Tooltip>
  )
}

/**
 * The trigger of a toolbar dropdown: an icon (or a short text value) and a
 * caret, with a tooltip. Render it inside `<DropdownMenu>`, or inside
 * `<Popover>` with `popover` for panels that hold plain buttons.
 */
export function ToolbarMenuTrigger({
  icon,
  label,
  value,
  disabled,
  active,
  popover = false,
  className,
  children,
}: {
  icon?: EditorAction["icon"]
  label: string
  value?: React.ReactNode
  disabled?: boolean
  active?: boolean
  popover?: boolean
  className?: string
  children?: React.ReactNode
}) {
  const Trigger = popover ? PopoverTrigger : DropdownMenuTrigger
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Trigger
            render={
              <Button
                type="button"
                variant="ghost"
                size="sm"
                aria-label={label}
                disabled={disabled}
                data-active={active || undefined}
                className={cn(
                  "gap-0.5 px-1.5 font-normal text-muted-foreground data-popup-open:bg-muted data-popup-open:text-foreground data-active:bg-muted data-active:text-foreground",
                  className
                )}
              />
            }
          />
        }
      >
        <ActionIcon icon={icon} />
        {value !== undefined && (
          <span className="truncate text-xs text-foreground">{value}</span>
        )}
        {children}
        <Icon icon="down" className="size-3 opacity-60" />
      </TooltipTrigger>
      <Hint label={label} />
    </Tooltip>
  )
}

export function ToolbarSeparator() {
  return (
    <Separator
      orientation="vertical"
      className="mx-0.5 h-4 self-center data-vertical:self-center"
    />
  )
}

import type {
  ActionSource,
  EditorAction,
  EditorActionContext,
  EditorController,
  EditorError,
} from "../types.ts"

/** Other names the toolbar and menus accept for built-in actions. */
const ALIASES: Record<string, string> = {
  code: "inlineCode",
  strikethrough: "strike",
  quote: "blockquote",
  divider: "horizontalRule",
  hr: "horizontalRule",
  checklist: "taskList",
  h1: "heading1",
  h2: "heading2",
  h3: "heading3",
}

export function resolveActionId(id: string) {
  return ALIASES[id] ?? id
}

/** What a menu or toolbar shows for an action at the current selection. */
export interface ActionState {
  visible: boolean
  enabled: boolean
  active: boolean
  running: boolean
}

/**
 * The snapshot an action runs with. The document's Markdown is serialized on
 * first read, so building a context per menu entry stays cheap.
 */
export function createActionContext(
  controller: EditorController,
  source: ActionSource
): EditorActionContext {
  const selection = Object.freeze(controller.getSelection())
  let markdown: string | undefined
  return Object.freeze({
    editor: controller,
    selection,
    selectedText: selection.text,
    get documentMarkdown() {
      return (markdown ??= controller.getMarkdown())
    },
    readOnly: controller.isReadOnly(),
    source,
  })
}

/** The fields menus and shortcuts depend on, to tell real changes apart. */
const signature = (actions: EditorAction[]) =>
  actions
    .map((action) =>
      [
        action.id,
        action.label,
        action.group,
        action.shortcut,
        action.slashCommand,
        typeof action.icon === "string" ? action.icon : "",
      ].join("\u0000")
    )
    .join("\u0001")

/**
 * Every action the editor knows, by id: the built-ins, the `actions` prop
 * and ones registered at runtime, later sources replacing earlier ones with
 * the same id. Running is guarded, so an action can't start twice at once,
 * and failures go to `onError` instead of throwing into a click handler.
 */
export class ActionRegistry {
  private builtIns = new Map<string, EditorAction>()
  private custom = new Map<string, EditorAction>()
  private runtime = new Map<string, EditorAction>()
  private running = new Set<string>()
  private listeners = new Set<() => void>()
  private version = 0
  private customSignature = ""
  private onError: (error: EditorError) => void

  constructor(onError: (error: EditorError) => void) {
    this.onError = onError
  }

  setBuiltIns(actions: EditorAction[]) {
    this.builtIns = new Map(actions.map((action) => [action.id, action]))
    this.notify()
  }

  /** Replaces the `actions` prop's set; only a visible change re-renders menus. */
  setCustom(actions: EditorAction[]) {
    this.custom = new Map(actions.map((action) => [action.id, action]))
    const next = signature(actions)
    if (next !== this.customSignature) {
      this.customSignature = next
      this.notify()
    }
  }

  register(action: EditorAction) {
    this.runtime.set(action.id, action)
    this.notify()
    return () => {
      if (this.runtime.get(action.id) !== action) return
      this.runtime.delete(action.id)
      this.notify()
    }
  }

  get(id: string): EditorAction | undefined {
    const key =
      this.runtime.has(id) || this.custom.has(id) ? id : resolveActionId(id)
    return (
      this.runtime.get(key) ?? this.custom.get(key) ?? this.builtIns.get(key)
    )
  }

  /** Built-ins first, then custom and runtime ones, each id once. */
  list(): EditorAction[] {
    const merged = new Map<string, EditorAction>()
    for (const source of [this.builtIns, this.custom, this.runtime]) {
      for (const [id, action] of source) merged.set(id, action)
    }
    return [...merged.values()]
  }

  /** Whether `id` is the editor's own action, not replaced by the app. */
  isBuiltIn(id: string) {
    return (
      this.builtIns.has(id) && !this.custom.has(id) && !this.runtime.has(id)
    )
  }

  isRunning(id: string) {
    return this.running.has(resolveActionId(id))
  }

  state(id: string, context: EditorActionContext): ActionState {
    const action = this.get(id)
    if (!action) {
      return { visible: false, enabled: false, active: false, running: false }
    }
    const visible = this.safely(action, () => action.isVisible?.(context), true)
    const allowed = !context.readOnly || Boolean(action.allowReadOnly)
    const enabled =
      visible &&
      allowed &&
      this.safely(action, () => action.isEnabled?.(context), true)
    return {
      visible,
      enabled,
      active: this.safely(action, () => action.isActive?.(context), false),
      running: this.running.has(action.id),
    }
  }

  /**
   * Runs an action with `context`. Resolves to whether it ran: unknown,
   * disabled, read-only and already-running actions don't, and a failing
   * one reports through `onError`.
   */
  async run(id: string, context: EditorActionContext): Promise<boolean> {
    const action = this.get(id)
    if (!action) {
      this.onError({
        code: "unknown-action",
        message: `There's no editor action "${id}".`,
        actionId: id,
      })
      return false
    }
    if (this.running.has(action.id)) return false
    if (context.readOnly && !action.allowReadOnly) {
      this.onError({
        code: "read-only",
        message: `"${action.label}" can't run while the editor is read-only.`,
        actionId: action.id,
      })
      return false
    }
    const { visible, enabled } = this.state(action.id, context)
    if (!visible || !enabled) return false

    this.running.add(action.id)
    this.notify()
    try {
      await action.execute(context)
      return true
    } catch (cause) {
      this.onError({
        code: "action-failed",
        message:
          cause instanceof Error ? cause.message : `"${action.label}" failed.`,
        actionId: action.id,
        cause,
      })
      return false
    } finally {
      this.running.delete(action.id)
      this.notify()
    }
  }

  subscribe = (listener: () => void) => {
    this.listeners.add(listener)
    return () => {
      this.listeners.delete(listener)
    }
  }

  getVersion = () => this.version

  private notify() {
    this.version += 1
    for (const listener of this.listeners) listener()
  }

  /** A predicate that throws counts as `fallback`, and is reported. */
  private safely(
    action: EditorAction,
    read: () => boolean | undefined,
    fallback: boolean
  ) {
    try {
      return read() ?? fallback
    } catch (cause) {
      this.onError({
        code: "action-failed",
        message: `"${action.label}" couldn't check whether it applies.`,
        actionId: action.id,
        cause,
      })
      return fallback
    }
  }
}

import { getHTMLFromFragment, type Editor } from "@tiptap/core"

import type { EditorController } from "../types.ts"

/** Thrown when the browser won't let a menu use the clipboard. */
export class ClipboardBlockedError extends Error {}

const shortcut = (key: string) =>
  typeof navigator !== "undefined" &&
  /Mac|iPhone|iPad/.test(navigator.userAgent)
    ? `⌘${key}`
    : `Ctrl+${key}`

function clipboard() {
  return typeof navigator !== "undefined" ? navigator.clipboard : undefined
}

/** Whether menus can paste (reading the clipboard needs this API). */
export function canReadClipboard() {
  return typeof clipboard()?.readText === "function"
}

/**
 * Copies the selection as rich text (HTML) with Markdown as its plain-text
 * form, falling back to Markdown alone where rich writes aren't allowed.
 */
export async function copySelection(
  editor: Editor,
  controller: EditorController
) {
  const api = clipboard()
  const markdown = controller.getSelectedMarkdown()
  if (!api || !markdown) {
    throw new ClipboardBlockedError(
      `The browser blocked copying from the menu. Use ${shortcut("C")} instead.`
    )
  }
  const { from, to } = editor.state.selection
  try {
    if (typeof ClipboardItem !== "undefined" && api.write) {
      const html = getHTMLFromFragment(
        editor.state.doc.slice(from, to).content,
        editor.schema
      )
      await api.write([
        new ClipboardItem({
          "text/plain": new Blob([markdown], { type: "text/plain" }),
          "text/html": new Blob([html], { type: "text/html" }),
        }),
      ])
      return
    }
  } catch {
    // Some browsers refuse rich writes but allow text; try that next.
  }
  try {
    await api.writeText(markdown)
  } catch {
    throw new ClipboardBlockedError(
      `The browser blocked copying from the menu. Use ${shortcut("C")} instead.`
    )
  }
}

/**
 * Pastes at the selection: HTML through the editor's schema (which drops
 * what it doesn't know), plain text as Markdown.
 */
export async function pasteClipboard(
  editor: Editor,
  controller: EditorController
) {
  const api = clipboard()
  const blocked = new ClipboardBlockedError(
    `The browser blocked pasting from the menu. Use ${shortcut("V")} instead.`
  )
  if (!api) throw blocked
  try {
    if (api.read) {
      const items = await api.read()
      for (const item of items) {
        if (item.types.includes("text/html")) {
          const html = await (await item.getType("text/html")).text()
          editor.chain().focus().insertContent(html).run()
          return
        }
      }
    }
  } catch {
    // Reading rich content is often refused where reading text isn't.
  }
  let text: string
  try {
    text = await api.readText()
  } catch {
    throw blocked
  }
  if (text) controller.insertMarkdown(text)
}

import type { Editor, JSONContent } from "@tiptap/core"

import type { AIController } from "../ai/ai-controller.ts"
import type {
  ContentOptions,
  EditorController,
  EditorError,
  EditorRange,
  EditorSelection,
  UrlPolicy,
} from "../types.ts"
import { ActionRegistry, createActionContext } from "./action-registry.ts"
import {
  insertableContent,
  parseMarkdown,
  serializeContent,
  serializeMarkdown,
} from "./markdown.ts"
import { isAlive, isMounted } from "./lifecycle.ts"
import { createBookmark, rangeText } from "./selection-manager.ts"

/** What the controller reads from the component that owns it. */
export interface ControllerHost {
  /** The current editor; it's replaced when the features change. */
  getEditor: () => Editor | null
  registry: ActionRegistry
  getUrlPolicy: () => UrlPolicy | undefined
  getAI: () => AIController | null
  onError: (error: EditorError) => void
}

/**
 * The editor's imperative API. It outlives any one Tiptap instance: every
 * call reads the current editor, so a `ref` stays valid when features change.
 */
export function createEditorController(host: ControllerHost): EditorController {
  const live = () => {
    const editor = host.getEditor()
    return isAlive(editor) ? editor : null
  }

  /** The editor if it may be changed now; reports why not otherwise. */
  const writable = (options?: ContentOptions) => {
    const editor = live()
    if (!editor) return null
    if (!editor.isEditable && !options?.ignoreReadOnly) {
      host.onError({
        code: "read-only",
        message: "The editor is read-only.",
      })
      return null
    }
    return editor
  }

  const parse = (editor: Editor, markdown: string) => {
    const { doc, removed } = parseMarkdown(
      editor,
      markdown,
      host.getUrlPolicy()
    )
    if (removed > 0) {
      host.onError({
        code: "unsafe-content",
        message: `Removed ${removed} link${removed === 1 ? "" : "s"} or image${removed === 1 ? "" : "s"} with a URL the editor doesn't allow.`,
      })
    }
    return doc
  }

  const validRange = (editor: Editor, range: EditorRange) => {
    const size = editor.state.doc.content.size
    const ok =
      Number.isInteger(range.from) &&
      Number.isInteger(range.to) &&
      range.from >= 0 &&
      range.from <= range.to &&
      range.to <= size
    if (!ok) {
      host.onError({
        code: "invalid-range",
        message: `${range.from}–${range.to} isn't a range in this document (0–${size}).`,
      })
    }
    return ok
  }

  /** Runs `change` as one transaction, kept out of history if asked. */
  const transact = (
    editor: Editor,
    options: ContentOptions | undefined,
    change: (chain: ReturnType<Editor["chain"]>) => ReturnType<Editor["chain"]>
  ) => {
    try {
      let chain = editor.chain()
      if (options?.skipHistory) {
        chain = chain.command(({ tr }) => {
          tr.setMeta("addToHistory", false)
          return true
        })
      }
      return change(chain).run()
    } catch (cause) {
      host.onError({
        code: "action-failed",
        message:
          cause instanceof Error ? cause.message : "The content didn't fit.",
        cause,
      })
      return false
    }
  }

  const replaceRange = (
    range: EditorRange,
    markdown: string,
    options?: ContentOptions
  ) => {
    const editor = writable(options)
    if (!editor || !validRange(editor, range)) return false
    const { doc } = editor.state
    const $from = doc.resolve(range.from)
    const $to = doc.resolve(range.to)
    // Inside a line of text a one-paragraph answer joins that line; at a
    // block boundary it stays a paragraph of its own.
    const inline = $from.parent.isTextblock && $to.parent.isTextblock
    const content = insertableContent(parse(editor, markdown), inline)
    return transact(editor, options, (chain) =>
      content.length
        ? chain.insertContentAt(range, content, { updateSelection: true })
        : chain.deleteRange(range)
    )
  }

  const getSelection = (): EditorSelection => {
    const editor = live()
    if (!editor) return { from: 0, to: 0, text: "", empty: true }
    const { from, to, empty } = editor.state.selection
    return { from, to, empty, text: rangeText(editor.state.doc, from, to) }
  }

  const controller: EditorController = {
    getMarkdown: () => {
      const editor = live()
      return editor ? serializeMarkdown(editor) : ""
    },

    setMarkdown: (markdown, options) => {
      const editor = writable(options)
      if (!editor) return false
      const doc = parse(editor, markdown)
      return transact(editor, options, (chain) =>
        chain.setContent(doc as JSONContent, { emitUpdate: true })
      )
    },

    clear: (options) => controller.setMarkdown("", options),

    insertMarkdown: (markdown, options) => {
      const { from, to } = getSelection()
      return replaceRange({ from, to }, markdown, options)
    },

    appendMarkdown: (markdown, options) => {
      const editor = writable(options)
      if (!editor) return false
      const blocks = parse(editor, markdown).content ?? []
      if (!blocks.length) return false
      const { doc } = editor.state
      const last = doc.lastChild
      const end = doc.content.size
      // An empty last paragraph (the one an empty editor has) is replaced.
      const range =
        last && last.type.name === "paragraph" && last.content.size === 0
          ? { from: end - last.nodeSize, to: end }
          : { from: end, to: end }
      return transact(editor, options, (chain) =>
        chain.insertContentAt(range, blocks, { updateSelection: false })
      )
    },

    replaceSelection: (markdown, options) =>
      controller.insertMarkdown(markdown, options),

    replaceRange,

    getSelection,

    getSelectedText: () => getSelection().text,

    getSelectedMarkdown: () => {
      const editor = live()
      if (!editor) return ""
      const { from, to, empty, $from, $to } = editor.state.selection
      if (empty) return ""
      // Within one line, the selection is its inline Markdown alone, not the
      // heading, list item or quote around it.
      if ($from.sameParent($to) && $from.parent.isTextblock) {
        const inline = $from.parent.content.cut(
          $from.parentOffset,
          $to.parentOffset
        )
        return serializeContent(editor, [
          { type: "paragraph", content: inline.toJSON() ?? [] },
        ])
      }
      return serializeContent(
        editor,
        editor.state.doc.slice(from, to).content.toJSON() ?? []
      )
    },

    setSelection: (range) => {
      const editor = live()
      if (!editor || !validRange(editor, range)) return
      editor.commands.setTextSelection(range)
    },

    bookmark: (range) => {
      const editor = live()
      if (!editor) {
        return { id: "", resolve: () => null, release: () => {} }
      }
      return createBookmark(editor, range ?? getSelection())
    },

    focus: (position) => {
      const editor = live()
      // Without a position, focus returns to the selection as it was.
      if (editor && isMounted(editor)) editor.commands.focus(position ?? null)
    },

    blur: () => {
      const editor = live()
      if (editor && isMounted(editor)) editor.commands.blur()
    },

    undo: () => {
      const editor = writable()
      return Boolean(editor?.can().undo?.() && editor.commands.undo())
    },

    redo: () => {
      const editor = writable()
      return Boolean(editor?.can().redo?.() && editor.commands.redo())
    },

    canUndo: () => {
      const editor = live()
      return Boolean(editor?.isEditable && editor.can().undo?.())
    },

    canRedo: () => {
      const editor = live()
      return Boolean(editor?.isEditable && editor.can().redo?.())
    },

    isEmpty: () => live()?.isEmpty ?? true,

    isReadOnly: () => !(live()?.isEditable ?? false),

    executeAction: async (id, source = "api") => {
      await host.registry.run(id, createActionContext(controller, source))
    },

    registerAction: (action) => host.registry.register(action),

    getActions: () => host.registry.list(),

    runAI: async (actionId, options) => {
      const ai = host.getAI()
      if (!ai) {
        host.onError({
          code: "unknown-action",
          message: "AI isn't enabled for this editor.",
          actionId,
        })
        return
      }
      await ai.start(actionId, options)
    },

    cancelAI: () => host.getAI()?.cancel(),

    getTiptapEditor: () => live(),
  }

  return controller
}

import { Extension, type Editor } from "@tiptap/core"

const destroyed = new WeakSet<Editor>()

/**
 * Records when an editor is destroyed. Tiptap's own `isDestroyed` is also
 * true for an editor that was never mounted, which a headless one isn't.
 */
export const EditorLifecycle = Extension.create({
  name: "editorLifecycle",

  onDestroy() {
    destroyed.add(this.editor)
  },
})

/** Whether the editor exists and hasn't been destroyed. */
export function isAlive(editor: Editor | null | undefined): editor is Editor {
  return Boolean(editor) && !destroyed.has(editor as Editor)
}

/** Whether the editor has a view in the page (a headless one doesn't). */
export function isMounted(editor: Editor | null | undefined) {
  if (!isAlive(editor)) return false
  try {
    return Boolean(editor.view.dom)
  } catch {
    return false
  }
}

/**
 * Keeps a controlled `value` and the document in step without echoes:
 *
 * - an edit reaches `onChange` only when the Markdown actually changed;
 * - the parent handing back what `onChange` gave it changes nothing;
 * - a genuinely new `value` replaces the document, and wins over an edit
 *   still waiting in the debounce.
 */
export class MarkdownSync {
  /** The Markdown the parent knows: what we last emitted or received. */
  private known: string
  private timer: ReturnType<typeof setTimeout> | null = null
  private read: () => string
  private emit: (markdown: string) => void
  private delay: () => number

  constructor(options: {
    initial: string
    /** Serializes the document now. */
    read: () => string
    emit: (markdown: string) => void
    /** Milliseconds to wait after an edit; 0 emits at once. */
    delay: () => number
  }) {
    this.known = options.initial
    this.read = options.read
    this.emit = options.emit
    this.delay = options.delay
  }

  /** The document changed through an edit or the controller. */
  changed() {
    const delay = this.delay()
    if (delay <= 0) {
      this.flush()
      return
    }
    if (this.timer) clearTimeout(this.timer)
    this.timer = setTimeout(() => this.flush(), delay)
  }

  /** Emits a waiting change now (on blur and unmount). */
  flush() {
    if (this.timer) clearTimeout(this.timer)
    this.timer = null
    const markdown = this.read()
    if (markdown === this.known) return
    this.known = markdown
    this.emit(markdown)
  }

  /**
   * A `value` arrived from the parent. Returns whether the document must be
   * replaced with it: not for our own echo, nor when it already says that.
   */
  received(value: string): boolean {
    if (value === this.known) return false
    if (this.timer) clearTimeout(this.timer)
    this.timer = null
    this.known = value
    return this.read() !== value
  }

  dispose() {
    if (this.timer) clearTimeout(this.timer)
    this.timer = null
  }
}

import {
  Extension,
  Mark,
  type AnyExtension,
  type Editor,
  type JSONContent,
  type MarkdownParseHelpers,
  type MarkdownRendererHelpers,
  type MarkdownToken,
  type MarkdownTokenizer,
} from "@tiptap/core"
import { Emoji } from "@tiptap/extension-emoji"
import { Subscript } from "@tiptap/extension-subscript"
import { Superscript } from "@tiptap/extension-superscript"
// Brings in the Markdown extension's `editor.markdown` and `getMarkdown` types.
import type {} from "@tiptap/markdown"

import type { ResolvedEditorFeatures, UrlPolicy } from "../types.ts"
import { defaultUrlPolicy, sanitizeContent } from "./security.ts"

/**
 * Markdown the editor has no feature for, kept verbatim. It's a code mark to
 * the serializer, so its text goes out exactly as it came in (no escaping),
 * and the next load reads the same syntax back into the same literal.
 */
export const MarkdownLiteral = Mark.create({
  name: "markdownLiteral",
  code: true,
  excludes: "_",
  inclusive: false,

  parseHTML() {
    return [{ tag: "span[data-markdown-literal]" }]
  },

  renderHTML() {
    return [
      "span",
      {
        "data-markdown-literal": "",
        class: "markdown-literal",
        title: "Markdown this editor doesn't format",
      },
      0,
    ]
  },

  renderMarkdown: (node, h) => h.renderChildren(node),
})

const literalText = (text: string): JSONContent => ({
  type: "text",
  text,
  marks: [{ type: "markdownLiteral" }],
})

/** A token's source as a literal block or inline run. */
function literalFor(token: MarkdownToken, level: "block" | "inline") {
  const raw = String(token.raw ?? "").replace(/\n+$/, "")
  if (!raw) return []
  return level === "block"
    ? { type: "paragraph", content: [literalText(raw)] }
    : literalText(raw)
}

/** A parse handler that keeps a token's source as literal text. */
function literalFallback(tokenName: string, level: "block" | "inline") {
  return Extension.create({
    name: `markdownLiteral_${tokenName}`,
    // After every real handler, so it only sees tokens they turned down.
    priority: 1,
    markdownTokenName: tokenName,
    parseMarkdown: (token: MarkdownToken) => literalFor(token, level),
  })
}

const TASK_ITEM = /^\s*[-+*]\s+\[[ xX]\]\s/

/**
 * Without checklists, a `- [ ]` list would otherwise become a plain bulleted
 * list and lose its checkboxes; this claims it first and keeps it literal.
 */
const TaskListLiteral = Extension.create({
  name: "markdownLiteral_taskList",
  priority: 1000,
  markdownTokenName: "list",
  parseMarkdown: (token: MarkdownToken) => {
    const items = (token.items ?? []) as MarkdownToken[]
    const tasks = items.some((item) => TASK_ITEM.test(String(item.raw ?? "")))
    return tasks ? literalFor(token, "block") : []
  },
})

/**
 * Literal fallbacks for the syntax of disabled features: a table in an
 * editor without tables stays as its Markdown source instead of vanishing.
 */
export function markdownFallbacks(
  features: ResolvedEditorFeatures
): AnyExtension[] {
  const fallbacks: [boolean, string, "block" | "inline"][] = [
    [features.headings, "heading", "block"],
    [features.blockquote, "blockquote", "block"],
    [features.codeBlock, "code", "block"],
    [features.bulletList && features.orderedList, "list", "block"],
    [features.horizontalRule, "hr", "block"],
    [features.tables, "table", "block"],
    [features.images, "image", "inline"],
    [features.bold, "strong", "inline"],
    [features.italic, "em", "inline"],
    [features.strike, "del", "inline"],
    [features.inlineCode, "codespan", "inline"],
    [features.links, "link", "inline"],
  ]
  const extensions = fallbacks
    .filter(([enabled]) => !enabled)
    .map(([, token, level]) => literalFallback(token, level))
  if (!features.taskList) extensions.push(TaskListLiteral)
  return extensions
}

/** `<sub>` / `<sup>` in Markdown, which has no syntax of its own for them. */
function htmlTagMarkdown(tag: "sub" | "sup", name: string) {
  const pattern = new RegExp(`^<${tag}>([\\s\\S]+?)</${tag}>`)
  const tokenizer: MarkdownTokenizer = {
    name,
    level: "inline",
    start: (src) => src.indexOf(`<${tag}>`),
    tokenize: (src, _tokens, lexer) => {
      const match = pattern.exec(src)
      if (!match) return undefined
      return {
        type: name,
        raw: match[0],
        text: match[1],
        tokens: lexer.inlineTokens(match[1]),
      }
    },
  }
  return {
    renderMarkdown: (node: JSONContent, h: MarkdownRendererHelpers) =>
      `<${tag}>${h.renderChildren(node)}</${tag}>`,
    parseMarkdown: (token: MarkdownToken, h: MarkdownParseHelpers) =>
      h.applyMark(name, h.parseInline(token.tokens ?? [])),
    markdownTokenizer: tokenizer,
  }
}

export const SubscriptMarkdown = Subscript.extend(
  htmlTagMarkdown("sub", "subscript")
)
export const SuperscriptMarkdown = Superscript.extend(
  htmlTagMarkdown("sup", "superscript")
)

/**
 * Emoji are saved as the emoji character, which every Markdown renderer
 * shows, rather than as a `:shortcode:` only this editor understands.
 */
export const EmojiMarkdown = Emoji.extend({
  renderMarkdown(node: JSONContent) {
    const name = String(node.attrs?.name ?? "")
    const item = this.options.emojis.find((emoji) => emoji.name === name)
    return item?.emoji ?? (name ? `:${name}:` : "")
  },
})

/**
 * Parses Markdown into document JSON for this editor's schema, with links
 * and images the URL policy refuses taken out.
 */
export function parseMarkdown(
  editor: Editor,
  markdown: string,
  policy: UrlPolicy = defaultUrlPolicy
): { doc: JSONContent; removed: number } {
  const manager = editor.markdown
  if (!manager) throw new Error("The editor has no Markdown extension.")
  const parsed = markdown.trim()
    ? manager.parse(markdown)
    : { type: "doc", content: [] }
  const { content, removed } = sanitizeContent(parsed, policy)
  return { doc: content, removed }
}

/**
 * Empty paragraphs serialize as extra blank lines (or `&nbsp;` lines), which
 * Markdown can't hold: they're gone on the next load. So runs of blank lines
 * become one, and blank lines at either end go. Code fences and `$$` blocks
 * keep theirs.
 */
export function tidyBlankLines(markdown: string): string {
  const out: string[] = []
  let fence: string | null = null
  let math = false
  for (const line of markdown.split("\n")) {
    const trimmed = line.trim()
    const marker = /^(`{3,}|~{3,})/.exec(trimmed)?.[1]
    if (fence) {
      if (marker && marker[0] === fence[0] && marker.length >= fence.length) {
        fence = null
      }
    } else if (marker) {
      fence = marker
    } else if (trimmed === "$$") {
      math = !math
    } else if (!math && (trimmed === "" || trimmed === "&nbsp;")) {
      if (out.length === 0 || out[out.length - 1] === "") continue
      out.push("")
      continue
    }
    out.push(line)
  }
  return out.join("\n").replace(/\s+$/, "")
}

/** The document as Markdown; an empty document is `""`. */
export function serializeMarkdown(editor: Editor): string {
  if (editor.isEmpty) return ""
  return tidyBlankLines(editor.getMarkdown())
}

/** Markdown for some blocks (a selection's slice, say). */
export function serializeContent(
  editor: Editor,
  content: JSONContent[]
): string {
  const manager = editor.markdown
  if (!manager || content.length === 0) return ""
  return manager.serialize({ type: "doc", content })
}

/**
 * What to insert for parsed Markdown: a lone paragraph becomes its inline
 * content (so it joins the line it's inserted into), anything else stays
 * blocks.
 */
export function insertableContent(
  doc: JSONContent,
  inline: boolean
): JSONContent[] {
  const blocks = doc.content ?? []
  if (inline && blocks.length === 1 && blocks[0].type === "paragraph") {
    return blocks[0].content ?? []
  }
  return blocks
}

/**
 * Closes what a half-streamed Markdown answer leaves open (code fences and
 * `$$` blocks), so a preview of it renders the way the finished one will.
 */
export function closeOpenMarkdown(markdown: string): string {
  let fence: string | null = null
  let math = false
  for (const line of markdown.split("\n")) {
    const trimmed = line.trim()
    const marker = /^(`{3,}|~{3,})/.exec(trimmed)?.[1]
    if (fence) {
      if (marker && marker[0] === fence[0] && marker.length >= fence.length) {
        fence = null
      }
    } else if (marker) {
      fence = marker
    } else if (trimmed === "$$") {
      math = !math
    }
  }
  if (fence) return `${markdown}\n${fence}`
  if (math) return `${markdown}\n$$`
  return markdown
}

import { Extension, type AnyExtension, type JSONContent } from "@tiptap/core"
import { gitHubEmojis } from "@tiptap/extension-emoji"
import type { EmojiOptions } from "@tiptap/extension-emoji"
import { Highlight } from "@tiptap/extension-highlight"
import { Image } from "@tiptap/extension-image"
import { TaskItem, TaskList } from "@tiptap/extension-list"
import { BlockMath, InlineMath } from "@tiptap/extension-mathematics"
import { Mention, type MentionOptions } from "@tiptap/extension-mention"
import {
  Table,
  TableCell,
  TableHeader,
  TableRow,
} from "@tiptap/extension-table"
import { Typography } from "@tiptap/extension-typography"
import { Markdown } from "@tiptap/markdown"
import { Marked, type marked } from "marked"
import type { Node as PMNode } from "@tiptap/pm/model"
import { StarterKit } from "@tiptap/starter-kit"

import type { ResolvedEditorFeatures, UrlPolicy } from "../types.ts"
import {
  EmojiMarkdown,
  MarkdownLiteral,
  SubscriptMarkdown,
  SuperscriptMarkdown,
  markdownFallbacks,
} from "./markdown.ts"
import { defaultUrlPolicy, sanitizeContent } from "./security.ts"
import { EditorLifecycle } from "./lifecycle.ts"
import { SelectionBookmarks } from "./selection-manager.ts"

/** The UI pieces the component plugs into the document extensions. */
export interface DocumentExtensionOptions {
  features: ResolvedEditorFeatures
  urlPolicy?: UrlPolicy
  /** Replaces the plain code block (with the highlighted one, say). */
  codeBlock?: AnyExtension
  /** Turns `@` mentions on, with this suggestion setup. */
  mention?: Partial<MentionOptions>["suggestion"]
  emojiSuggestion?: Partial<EmojiOptions>["suggestion"]
  onMathClick?: (
    kind: "inlineMath" | "blockMath",
    node: PMNode,
    pos: number
  ) => void
  /** Told how many unsafe links and images the initial content lost. */
  onUnsafeContent?: (removed: number) => void
}

/**
 * Cleans the content an editor starts with, once the Markdown extension has
 * parsed it: links and images the URL policy refuses are taken out, and an
 * empty string becomes an empty document (Tiptap would otherwise read it as
 * HTML, which needs a page).
 */
const InitialContent = Extension.create<{
  policy: UrlPolicy
  onUnsafe?: (removed: number) => void
}>({
  name: "initialContent",
  // After the Markdown extension (100), which turns the string into JSON.
  priority: 50,

  onBeforeCreate() {
    const { options } = this.editor
    const content = options.content
    if (typeof content === "string" && !content.trim()) {
      options.content = { type: "doc", content: [{ type: "paragraph" }] }
    } else if (
      content &&
      typeof content === "object" &&
      !Array.isArray(content)
    ) {
      const clean = sanitizeContent(content as JSONContent, this.options.policy)
      options.content = clean.content
      if (clean.removed) this.options.onUnsafe?.(clean.removed)
    }
  },
})

// GFM cells hold one line of inline text; paragraphs in a cell are joined
// with <br> on the way out and split on the way back in.
const MarkdownTableCell = TableCell.extend({ content: "paragraph+" })
const MarkdownTableHeader = TableHeader.extend({ content: "paragraph+" })

/**
 * The extensions that define the document and its Markdown: nodes, marks,
 * history, input rules, literal fallbacks for disabled syntax and selection
 * bookmarks. Everything here works without a page, so it's what the tests
 * load; the component adds its menus and views on top.
 */
export function createDocumentExtensions({
  features,
  urlPolicy = defaultUrlPolicy,
  codeBlock,
  mention,
  emojiSuggestion,
  onMathClick,
  onUnsafeContent,
}: DocumentExtensionOptions): AnyExtension[] {
  const lists = features.bulletList || features.orderedList
  const extensions: AnyExtension[] = [
    StarterKit.configure({
      bold: features.bold ? {} : false,
      italic: features.italic ? {} : false,
      underline: features.underline ? {} : false,
      strike: features.strike ? {} : false,
      code: features.inlineCode ? {} : false,
      link: features.links
        ? {
            openOnClick: false,
            autolink: true,
            linkOnPaste: true,
            defaultProtocol: "https",
            isAllowedUri: (url, context) =>
              context.defaultValidate(url) && urlPolicy(url, "link"),
          }
        : false,
      heading: features.headings ? { levels: [1, 2, 3, 4, 5, 6] } : false,
      blockquote: features.blockquote ? {} : false,
      bulletList: features.bulletList ? {} : false,
      orderedList: features.orderedList ? {} : false,
      listItem: lists ? {} : false,
      listKeymap: lists || features.taskList ? {} : false,
      codeBlock: features.codeBlock && !codeBlock ? {} : false,
      horizontalRule: features.horizontalRule ? {} : false,
      undoRedo: features.history ? { depth: 200 } : false,
      dropcursor: { color: "var(--focus)", width: 2 },
    }),
    Markdown.configure({
      indentation: { style: "space", size: 2 },
      // Tiptap registers each extension's tokenizer on the parser it's
      // given; a parser of its own keeps another editor's syntax (math,
      // mentions, highlights) from leaking into this one.
      marked: new Marked() as unknown as typeof marked,
    }),
    InitialContent.configure({ policy: urlPolicy, onUnsafe: onUnsafeContent }),
    MarkdownLiteral,
    ...markdownFallbacks(features),
    SelectionBookmarks,
    EditorLifecycle,
  ]

  if (features.codeBlock && codeBlock) extensions.push(codeBlock)
  if (features.highlight) extensions.push(Highlight)
  if (features.subscript) extensions.push(SubscriptMarkdown)
  if (features.superscript) extensions.push(SuperscriptMarkdown)
  if (features.typography) extensions.push(Typography)
  if (features.taskList) {
    extensions.push(TaskList, TaskItem.configure({ nested: true }))
  }
  if (features.tables) {
    extensions.push(
      // Column widths have no Markdown, so columns aren't resizable.
      Table.configure({ resizable: false }),
      TableRow,
      MarkdownTableHeader,
      MarkdownTableCell
    )
  }
  if (features.images) {
    extensions.push(
      Image.extend({
        // Pasted or dropped HTML only brings images the URL policy allows.
        parseHTML() {
          return [
            {
              tag: "img[src]",
              getAttrs: (element) =>
                urlPolicy(element.getAttribute("src") ?? "", "image")
                  ? null
                  : false,
            },
          ]
        },
      }).configure({ allowBase64: true })
    )
  }
  if (features.math) {
    // Configured apart, so blocks render in KaTeX display mode.
    extensions.push(
      InlineMath.configure({
        katexOptions: { throwOnError: false },
        onClick: onMathClick
          ? (node, pos) => onMathClick("inlineMath", node, pos)
          : undefined,
      }),
      BlockMath.configure({
        katexOptions: { throwOnError: false, displayMode: true },
        onClick: onMathClick
          ? (node, pos) => onMathClick("blockMath", node, pos)
          : undefined,
      })
    )
  }
  if (features.emoji) {
    extensions.push(
      EmojiMarkdown.configure({
        emojis: gitHubEmojis,
        enableEmoticons: true,
        ...(emojiSuggestion && { suggestion: emojiSuggestion }),
      })
    )
  }
  if (mention) {
    extensions.push(
      Mention.configure({
        HTMLAttributes: { class: "mention" },
        deleteTriggerWithBackspace: true,
        suggestion: mention,
      })
    )
  }
  return extensions
}

import type { JSONContent } from "@tiptap/core"

import type { UrlPolicy } from "../types.ts"

const LINK_SCHEMES = new Set(["http:", "https:", "mailto:", "tel:"])
const IMAGE_SCHEMES = new Set(["http:", "https:", "blob:"])
// Nodes whose children are inline (an unsafe image inside one becomes text).
const TEXTBLOCKS = new Set(["paragraph", "heading"])
// Raster formats only: SVG can carry script when opened on its own.
const DATA_IMAGE =
  /^data:image\/(?:png|jpe?g|gif|webp|avif);base64,[a-z\d+/=\s]+$/i

/** The scheme of an absolute URL (`https:`), or null for a relative one. */
function scheme(url: string) {
  // Browsers ignore control characters and whitespace inside schemes
  // (`java\nscript:`), so they don't count as a way around the check.
  // eslint-disable-next-line no-control-regex
  const compact = url.replace(/[\x00-\x20\x7f]/g, "")
  const match = /^([a-z][a-z\d+.-]*):/i.exec(compact)
  return match ? `${match[1].toLowerCase()}:` : null
}

/**
 * The default policy: links may be web, mail, phone or relative URLs;
 * images may be web or blob URLs, or inline PNG, JPEG, GIF, WebP or AVIF.
 * `javascript:`, `vbscript:`, `data:` links and the like are refused.
 */
export const defaultUrlPolicy: UrlPolicy = (url, kind) => {
  const value = url.trim()
  if (!value) return false
  const found = scheme(value)
  if (kind === "image" && found === "data:") return DATA_IMAGE.test(value)
  if (found === null) return true
  return (kind === "link" ? LINK_SCHEMES : IMAGE_SCHEMES).has(found)
}

/**
 * Removes what the policy refuses from parsed content: unsafe links lose the
 * link but keep their text, unsafe images become their alt text. Returns the
 * cleaned content and how many things were removed.
 */
export function sanitizeContent(
  content: JSONContent,
  policy: UrlPolicy = defaultUrlPolicy
): { content: JSONContent; removed: number } {
  let removed = 0

  const visit = (node: JSONContent, inText: boolean): JSONContent | null => {
    if (node.type === "image") {
      const src = String(node.attrs?.src ?? "")
      if (!policy(src, "image")) {
        removed += 1
        const alt = String(node.attrs?.alt ?? "").trim()
        if (!alt) return null
        const text = { type: "text", text: alt }
        return inText ? text : { type: "paragraph", content: [text] }
      }
    }
    let next = node
    if (node.marks?.length) {
      const marks = node.marks.filter((mark) => {
        if (mark.type !== "link") return true
        const ok = policy(String(mark.attrs?.href ?? ""), "link")
        if (!ok) removed += 1
        return ok
      })
      if (marks.length !== node.marks.length) next = { ...next, marks }
    }
    if (node.content) {
      const textblock = TEXTBLOCKS.has(node.type ?? "")
      const children = node.content
        .map((child) => visit(child, textblock))
        .filter((child): child is JSONContent => child !== null)
      next = { ...next, content: children }
    }
    return next
  }

  return {
    content: visit(content, false) ?? { type: "doc", content: [] },
    removed,
  }
}

import { Extension, type Editor } from "@tiptap/core"
import type { Node as PMNode } from "@tiptap/pm/model"
import { Plugin, PluginKey, type Transaction } from "@tiptap/pm/state"
import { Decoration, DecorationSet } from "@tiptap/pm/view"

import type { EditorBookmark, EditorRange } from "../types.ts"
import { isAlive } from "./lifecycle.ts"

interface Bookmark {
  from: number
  to: number
  /** The text when it was taken; a range whose text changed is lost. */
  text: string
  lost: boolean
  /** Tint the range while something works on it. */
  highlight: boolean
}

interface BookmarkState {
  bookmarks: Map<string, Bookmark>
  decorations: DecorationSet
}

type BookmarkMeta =
  | { add: { id: string; from: number; to: number; highlight: boolean } }
  | { remove: string }

export const bookmarkKey = new PluginKey<BookmarkState>("selectionBookmarks")

/** The text a bookmark compares, blocks joined by newlines. */
export function rangeText(doc: PMNode, from: number, to: number) {
  return doc.textBetween(from, to, "\n", "\ufffc")
}

function decorate(doc: PMNode, bookmarks: Map<string, Bookmark>) {
  const decorations: Decoration[] = []
  for (const bookmark of bookmarks.values()) {
    if (!bookmark.highlight || bookmark.lost || bookmark.from >= bookmark.to) {
      continue
    }
    decorations.push(
      Decoration.inline(bookmark.from, bookmark.to, {
        class: "rich-text-pending",
      })
    )
  }
  return DecorationSet.create(doc, decorations)
}

function mapBookmark(bookmark: Bookmark, tr: Transaction): Bookmark {
  // Text typed at either edge stays outside the range; a caret bookmark
  // moves past what's typed at it, so work lands after the new text.
  const empty = bookmark.from === bookmark.to
  const from = tr.mapping.mapResult(bookmark.from, 1)
  const to = tr.mapping.mapResult(bookmark.to, empty ? 1 : -1)
  const lost =
    bookmark.lost ||
    to.pos < from.pos ||
    (empty ? from.deleted : from.deletedAfter && to.deletedBefore)
  return { ...bookmark, from: from.pos, to: Math.max(from.pos, to.pos), lost }
}

/**
 * Ranges that follow edits: anything that works on the selection after a
 * wait (AI, uploads, async actions) bookmarks it first, then resolves the
 * bookmark to find where that text is now, or learns that it has changed.
 */
export const SelectionBookmarks = Extension.create({
  name: "selectionBookmarks",

  addProseMirrorPlugins() {
    return [
      new Plugin<BookmarkState>({
        key: bookmarkKey,
        state: {
          init: (_, state) => ({
            bookmarks: new Map(),
            decorations: DecorationSet.create(state.doc, []),
          }),
          apply: (tr, previous) => {
            const meta = tr.getMeta(bookmarkKey) as BookmarkMeta | undefined
            if (!tr.docChanged && !meta) return previous
            let bookmarks = previous.bookmarks
            if (tr.docChanged) {
              bookmarks = new Map(
                [...bookmarks].map(([id, bookmark]) => [
                  id,
                  mapBookmark(bookmark, tr),
                ])
              )
            }
            if (meta && "add" in meta) {
              const { id, from, to, highlight } = meta.add
              bookmarks = new Map(bookmarks).set(id, {
                from,
                to,
                text: rangeText(tr.doc, from, to),
                lost: false,
                highlight,
              })
            } else if (meta && "remove" in meta) {
              bookmarks = new Map(bookmarks)
              bookmarks.delete(meta.remove)
            }
            return { bookmarks, decorations: decorate(tr.doc, bookmarks) }
          },
        },
        props: {
          decorations: (state) => bookmarkKey.getState(state)?.decorations,
        },
      }),
    ]
  },
})

let nextId = 0

function dispatchMeta(editor: Editor, meta: BookmarkMeta) {
  if (!isAlive(editor)) return
  const tr = editor.state.tr
    .setMeta(bookmarkKey, meta)
    .setMeta("addToHistory", false)
  editor.view.dispatch(tr)
}

/**
 * Bookmarks `range` (clamped to the document). `resolve` returns where it
 * is now, or null once its text has changed or been deleted.
 */
export function createBookmark(
  editor: Editor,
  range: EditorRange,
  { highlight = false }: { highlight?: boolean } = {}
): EditorBookmark {
  const id = `bookmark-${(nextId += 1)}`
  const size = editor.state.doc.content.size
  const from = Math.max(0, Math.min(range.from, size))
  const to = Math.max(from, Math.min(range.to, size))
  dispatchMeta(editor, { add: { id, from, to, highlight } })
  let released = false

  return {
    id,
    resolve: () => {
      if (released || !isAlive(editor)) return null
      const bookmark = bookmarkKey.getState(editor.state)?.bookmarks.get(id)
      if (!bookmark || bookmark.lost) return null
      const now = rangeText(editor.state.doc, bookmark.from, bookmark.to)
      if (now !== bookmark.text) return null
      return { from: bookmark.from, to: bookmark.to }
    },
    release: () => {
      if (released) return
      released = true
      dispatchMeta(editor, { remove: id })
    },
  }
}

import { EditorContent } from "@tiptap/react"
import { cn } from "cn"

import { useRichTextEditorContext } from "./context"

/**
 * The editable text, in the editor's typography. `RichTextEditor` renders
 * it; a headless editor renders it inside `RichTextEditorProvider`.
 */
export function RichTextEditorContent({
  className,
  focusMode = false,
  bare = false,
}: {
  className?: string
  /** Dims every block but the one being edited. */
  focusMode?: boolean
  /** No padding around the text, for showing it inside something else. */
  bare?: boolean
}) {
  const { editor, features } = useRichTextEditorContext()
  const editable = editor.isEditable
  return (
    <EditorContent
      editor={editor}
      data-editable={editable || undefined}
      data-drag-handle={(editable && features.dragHandle) || undefined}
      data-focus-mode={focusMode || undefined}
      data-bare={bare || undefined}
      className={cn("rich-text relative min-h-[inherit]", className)}
    />
  )
}

import { Extension, type AnyExtension, type Editor } from "@tiptap/core"
import { CodeBlockLowlight } from "@tiptap/extension-code-block-lowlight"
import type { EmojiItem } from "@tiptap/extension-emoji"
import { FileHandler } from "@tiptap/extension-file-handler"
import { FindAndReplace } from "@tiptap/extension-find-and-replace"
import { InvisibleCharacters } from "@tiptap/extension-invisible-characters"
import {
  CharacterCount,
  Focus,
  Placeholder,
  Selection,
} from "@tiptap/extensions"
import { keydownHandler } from "@tiptap/pm/keymap"
import { Plugin, PluginKey } from "@tiptap/pm/state"
import { ReactNodeViewRenderer } from "@tiptap/react"

import { CodeBlockView } from "./code-block-view"
import {
  createActionContext,
  type ActionRegistry,
} from "./core/action-registry"
import { createDocumentExtensions } from "./core/schema"
import { IMAGE_TYPES } from "./files"
import { lowlight } from "./lowlight"
import { MarkdownPaste } from "./markdown-paste"
import { SlashCommand } from "./slash-command"
import { suggestionRenderer } from "./suggestion"
import type {
  EditorController,
  EditorUiHandlers,
  MentionItem,
  MentionSource,
  ResolvedEditorFeatures,
  UrlPolicy,
} from "./types"

/**
 * Callbacks the extensions call into the component with. The object is
 * stable and reads the latest props itself, so the editor never rebuilds
 * for a new callback.
 */
export interface EditorHandlers {
  ui: () => EditorUiHandlers
  registry: ActionRegistry
  controller: EditorController
  insertFiles: (editor: Editor, files: File[], pos?: number) => void
  placeholder: () => string
  mentions: MentionSource
  urlPolicy: () => UrlPolicy | undefined
  onUnsafeContent: (removed: number) => void
}

export interface ExtensionConfig {
  features: ResolvedEditorFeatures
  maxLength?: number
  /** Whether `@` suggests people (the source itself comes from handlers). */
  mentions: boolean
  urlPolicy?: UrlPolicy
  handlers: EditorHandlers
  /** The app's own extensions, added last. */
  extensions?: AnyExtension[]
}

/**
 * Editor-level keys: ⌘K links, ⌘F finds, ⌘⇧Enter toggles full screen and
 * Escape leaves it. Low priority, so open suggestion menus get Escape first.
 */
const Shortcuts = Extension.create<{ handlers: EditorHandlers }>({
  name: "richTextShortcuts",
  priority: 10,

  addKeyboardShortcuts() {
    const { registry, controller, ui } = this.options.handlers
    const run = (id: string) => {
      if (!registry.get(id)) return false
      void registry.run(id, createActionContext(controller, "shortcut"))
      return true
    }
    return {
      "Mod-k": () => run("link"),
      "Mod-f": () => run("find"),
      "Mod-Shift-Enter": () => run("fullscreen"),
      Escape: () => {
        if (!ui().viewState().fullscreen) return false
        ui().toggleFullscreen(false)
        return true
      },
    }
  },
})

/**
 * Binds the shortcuts of the app's own actions. Built-in actions keep the
 * bindings their extensions own; an app action with the same keys wins.
 */
const ActionShortcuts = Extension.create<{ handlers: EditorHandlers }>({
  name: "actionShortcuts",
  priority: 1000,

  addProseMirrorPlugins() {
    const { registry, controller } = this.options.handlers
    let version = -1
    let handler: ReturnType<typeof keydownHandler> | null = null
    return [
      new Plugin({
        key: new PluginKey("actionShortcuts"),
        props: {
          handleKeyDown: (view, event) => {
            if (registry.getVersion() !== version) {
              version = registry.getVersion()
              const bindings: Record<string, () => boolean> = {}
              for (const action of registry.list()) {
                if (!action.shortcut || registry.isBuiltIn(action.id)) continue
                bindings[action.shortcut] = () => {
                  void registry.run(
                    action.id,
                    createActionContext(controller, "shortcut")
                  )
                  return true
                }
              }
              handler = keydownHandler(bindings)
            }
            return handler?.(view, event) ?? false
          },
        },
      }),
    ]
  },
})

function emojiItems(emojis: EmojiItem[], query: string) {
  const q = query.toLowerCase()
  return emojis
    .filter(
      ({ shortcodes, tags }) =>
        shortcodes.some((code) => code.startsWith(q)) ||
        tags.some((tag) => tag.startsWith(q))
    )
    .slice(0, 8)
}

/**
 * Every extension the editor loads: the document's (shared with the
 * tests), the views and suggestion menus that need React, then the tools.
 */
export function createEditorExtensions({
  features,
  maxLength,
  mentions,
  urlPolicy,
  handlers,
  extensions: custom = [],
}: ExtensionConfig): AnyExtension[] {
  const extensions = createDocumentExtensions({
    features,
    urlPolicy,
    onUnsafeContent: handlers.onUnsafeContent,
    codeBlock: features.codeHighlighting
      ? CodeBlockLowlight.extend({
          addNodeView: () => ReactNodeViewRenderer(CodeBlockView),
        }).configure({ lowlight, enableTabIndentation: true, tabSize: 2 })
      : undefined,
    onMathClick: (kind, node, pos) => {
      if (!handlers.controller.isReadOnly()) {
        handlers.ui().openDialog({
          kind,
          pos,
          initial: String(node.attrs.latex ?? ""),
        })
      }
    },
    emojiSuggestion: {
      items: ({ editor, query }) =>
        emojiItems(editor.storage.emoji.emojis, query),
      render: suggestionRenderer<EmojiItem>({
        label: "Emoji",
        empty: "No matching emoji",
        getKey: (item) => item.name,
        renderItem: (item) => (
          <>
            <span className="grid w-5 place-items-center text-base leading-none">
              {item.emoji ??
                (item.fallbackImage && (
                  <img src={item.fallbackImage} alt="" className="size-4" />
                ))}
            </span>
            <span className="truncate">:{item.shortcodes[0]}:</span>
          </>
        ),
      }),
    },
    mention: mentions
      ? {
          debounce: 150,
          items: ({ query, signal }) => handlers.mentions(query, signal),
          render: suggestionRenderer<MentionItem>({
            label: "People",
            empty: "No one matches",
            getKey: (item) => item.id,
            renderItem: (item) => (
              <span className="flex min-w-0 flex-col">
                <span className="truncate text-foreground">{item.label}</span>
                {item.description && (
                  <span className="truncate text-2xs text-muted-foreground">
                    {item.description}
                  </span>
                )}
              </span>
            ),
          }),
        }
      : undefined,
  })

  extensions.push(
    Shortcuts.configure({ handlers }),
    ActionShortcuts.configure({ handlers }),
    Placeholder.configure({
      includeChildren: true,
      placeholder: ({ editor, node }) => {
        if (node.type.name === "heading") return `Heading ${node.attrs.level}`
        if (editor.isEmpty) return handlers.placeholder()
        return features.slashCommands ? "Type / for commands" : ""
      },
    }),
    CharacterCount.configure({ limit: maxLength ?? null }),
    Focus.configure({ className: "has-focus", mode: "shallowest" }),
    Selection.configure({ className: "selection" }),
    MarkdownPaste.configure({
      getUrlPolicy: handlers.urlPolicy,
      onUnsafe: handlers.onUnsafeContent,
    })
  )

  if (features.images) {
    extensions.push(
      FileHandler.configure({
        allowedMimeTypes: IMAGE_TYPES,
        onDrop: (editor, files, pos) =>
          handlers.insertFiles(editor, files, pos),
        // A copy that also carries HTML (an image copied from a web page)
        // pastes through the HTML; only bare files are inserted here.
        onPaste: (editor, files, html) => {
          if (!html) handlers.insertFiles(editor, files)
        },
      })
    )
  }
  if (features.slashCommands) {
    extensions.push(
      SlashCommand.configure({
        registry: handlers.registry,
        controller: handlers.controller,
      })
    )
  }
  if (features.findReplace) {
    extensions.push(FindAndReplace.configure({ injectCSS: false }))
  }
  if (features.invisibleCharacters) {
    extensions.push(InvisibleCharacters.configure({ visible: false }))
  }
  return [...extensions, ...custom]
}

import type { Editor } from "@tiptap/react"

import type { UploadHandler, UrlPolicy } from "./types"

export const IMAGE_TYPES = [
  "image/png",
  "image/jpeg",
  "image/gif",
  "image/webp",
  "image/avif",
]

function readAsDataUrl(file: File) {
  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(String(reader.result))
    reader.onerror = () => reject(reader.error ?? new Error("Unreadable file"))
    reader.readAsDataURL(file)
  })
}

function formatBytes(bytes: number) {
  if (bytes >= 1024 * 1024) return `${Math.round(bytes / 1024 / 1024)} MB`
  return `${Math.round(bytes / 1024)} KB`
}

/**
 * Uploads (or inlines) each image and inserts it at `pos`, or at the
 * selection. Files the editor can't hold are reported, not dropped silently.
 */
export async function insertFiles(
  editor: Editor,
  files: File[],
  {
    upload,
    maxFileSize,
    pos,
    urlPolicy,
    onError,
  }: {
    upload?: UploadHandler
    maxFileSize: number
    pos?: number
    urlPolicy: UrlPolicy
    onError: (message: string) => void
  }
) {
  let at = pos
  for (const file of files) {
    if (!IMAGE_TYPES.includes(file.type) || !editor.schema.nodes.image) {
      onError(`${file.name} isn't an image this editor accepts.`)
      continue
    }
    if (file.size > maxFileSize) {
      onError(`${file.name} is over the ${formatBytes(maxFileSize)} limit.`)
      continue
    }
    try {
      const src = upload ? await upload(file) : await readAsDataUrl(file)
      if (!urlPolicy(src, "image")) {
        onError(`${file.name} came back with a URL the editor doesn't allow.`)
        continue
      }
      const node = { type: "image", attrs: { src, alt: file.name } }
      if (at === undefined) {
        editor.chain().focus().insertContent(node).run()
      } else {
        // The document may have changed while the upload ran.
        at = Math.min(at, editor.state.doc.content.size)
        editor.chain().insertContentAt(at, node).focus().run()
        at = editor.state.selection.to
      }
    } catch (error) {
      onError(
        `${file.name} couldn't be added: ${error instanceof Error ? error.message : String(error)}`
      )
    }
  }
}

import * as React from "react"
import {
  CaseSensitiveIcon,
  RegexIcon,
  ReplaceAllIcon,
  ReplaceIcon,
  WholeWordIcon,
} from "@hugeicons/core-free-icons"
import { useEditorState, type Editor } from "@tiptap/react"

import { Input } from "@/components/ui/input"
import { ToolbarAction, ToolbarToggle } from "./controls"

/**
 * ⌘F search over the document: matches highlight as you type, Enter and
 * ⇧Enter step through them, and Replace swaps the current one or all.
 */
export function FindReplaceBar({
  editor,
  onClose,
}: {
  editor: Editor
  onClose: () => void
}) {
  const search = useEditorState({
    editor,
    selector: ({ editor }) => {
      const storage = editor.storage.findAndReplace
      if (!storage) return null
      return {
        total: storage.results.length,
        current: storage.currentIndex,
        caseSensitive: storage.caseSensitive,
        useRegex: storage.useRegex,
        wholeWord: storage.wholeWord,
      }
    },
  })
  // Searching the selected text is the usual way in.
  const [initialTerm] = React.useState(() => {
    const { from, to, empty } = editor.state.selection
    const selected = empty ? "" : editor.state.doc.textBetween(from, to, " ")
    return selected && !selected.includes("\n") && selected.length < 200
      ? selected
      : (editor.storage.findAndReplace?.searchTerm ?? "")
  })
  const [term, setTerm] = React.useState(initialTerm)
  const [replacement, setReplacement] = React.useState(
    () => editor.storage.findAndReplace?.replaceTerm ?? ""
  )
  const findRef = React.useRef<HTMLInputElement>(null)
  const readOnly = !editor.isEditable

  React.useEffect(() => {
    if (initialTerm) editor.commands.setSearchTerm(initialTerm)
    findRef.current?.focus()
    findRef.current?.select()
  }, [editor, initialTerm])

  if (!search) return null

  const close = () => {
    editor.commands.clearSearch()
    onClose()
    editor.commands.focus()
  }

  const onKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === "Escape") {
      event.preventDefault()
      close()
    }
  }

  const count = !term
    ? ""
    : search.total === 0
      ? "No results"
      : `${search.current === null ? "–" : search.current + 1} of ${search.total}`

  return (
    <div
      role="search"
      aria-label="Find and replace"
      data-slot="rich-text-find"
      onKeyDown={onKeyDown}
      className="flex flex-wrap items-center gap-x-2 gap-y-1 border-b border-border bg-muted/40 px-2 py-1.5"
    >
      <div className="flex min-w-56 flex-1 items-center gap-0.5">
        <Input
          ref={findRef}
          aria-label="Find"
          placeholder="Find"
          value={term}
          onChange={(event) => {
            setTerm(event.target.value)
            editor.commands.setSearchTerm(event.target.value)
          }}
          onKeyDown={(event) => {
            if (event.key !== "Enter") return
            event.preventDefault()
            if (event.shiftKey) editor.commands.goToPreviousResult()
            else editor.commands.goToNextResult()
          }}
          className="h-7 min-w-0 flex-1 text-xs md:text-xs"
        />
        <span
          aria-live="polite"
          className="w-[4.5rem] shrink-0 text-center text-2xs text-muted-foreground tabular-nums"
        >
          {count}
        </span>
        <ToolbarToggle
          icon={CaseSensitiveIcon}
          label="Match case"
          pressed={search.caseSensitive}
          onPressedChange={() =>
            editor.commands.setCaseSensitive(!search.caseSensitive)
          }
        />
        <ToolbarToggle
          icon={WholeWordIcon}
          label="Whole words"
          pressed={search.wholeWord}
          onPressedChange={() =>
            editor.commands.setWholeWord(!search.wholeWord)
          }
        />
        <ToolbarToggle
          icon={RegexIcon}
          label="Regular expression"
          pressed={search.useRegex}
          onPressedChange={() => editor.commands.setUseRegex(!search.useRegex)}
        />
        <ToolbarAction
          icon="up"
          label="Previous match"
          shortcut="Shift-Enter"
          disabled={!search.total}
          onClick={() => editor.commands.goToPreviousResult()}
        />
        <ToolbarAction
          icon="down"
          label="Next match"
          shortcut="Enter"
          disabled={!search.total}
          onClick={() => editor.commands.goToNextResult()}
        />
      </div>
      {!readOnly && (
        <div className="flex min-w-56 flex-1 items-center gap-0.5">
          <Input
            aria-label="Replace with"
            placeholder="Replace with"
            value={replacement}
            onChange={(event) => {
              setReplacement(event.target.value)
              editor.commands.setReplaceTerm(event.target.value)
            }}
            onKeyDown={(event) => {
              if (event.key !== "Enter") return
              event.preventDefault()
              if (event.metaKey || event.ctrlKey) editor.commands.replaceAll()
              else editor.commands.replace()
            }}
            className="h-7 min-w-0 flex-1 text-xs md:text-xs"
          />
          <ToolbarAction
            icon={ReplaceIcon}
            label="Replace"
            shortcut="Enter"
            disabled={!search.total}
            onClick={() => editor.commands.replace()}
          />
          <ToolbarAction
            icon={ReplaceAllIcon}
            label="Replace all"
            shortcut="Mod-Enter"
            disabled={!search.total}
            onClick={() => editor.commands.replaceAll()}
          />
        </div>
      )}
      <ToolbarAction
        icon="close"
        label="Close"
        shortcut="Escape"
        onClick={close}
      />
    </div>
  )
}

import * as React from "react"
import { Upload01Icon } from "@hugeicons/core-free-icons"
import type { Editor } from "@tiptap/react"
import katex from "katex"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import {
  Field,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Icon } from "../icon"
import { formatShortcut } from "./shortcuts"
import type {
  EditorUiHandlers,
  InsertDialogKind,
  InsertDialogRequest,
  UrlPolicy,
} from "./types"

const COPY: Record<
  InsertDialogKind,
  { title: string; description: string; field: string; placeholder: string }
> = {
  link: {
    title: "Link",
    description: "Link the selected text to a page, file or email address.",
    field: "URL",
    placeholder: "https://example.com",
  },
  image: {
    title: "Image",
    description: "Upload an image, or link one that's already online.",
    field: "Image URL",
    placeholder: "https://example.com/diagram.png",
  },
  inlineMath: {
    title: "Inline formula",
    description: "Write LaTeX; it renders inside the line of text.",
    field: "LaTeX",
    placeholder: "E = mc^2",
  },
  blockMath: {
    title: "Formula block",
    description: "Write LaTeX; it renders as a centred equation.",
    field: "LaTeX",
    placeholder: "\\int_0^\\infty e^{-x^2}\\,dx = \\frac{\\sqrt{\\pi}}{2}",
  },
}

/** Adds `https://` to bare domains; leaves mailto:, tel:, # and / links. */
function normalizeHref(value: string) {
  const href = value.trim()
  if (!href) return ""
  if (/^([a-z][a-z\d+.-]*:|#|\/)/i.test(href)) return href
  if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(href)) return `mailto:${href}`
  return `https://${href}`
}

function initialValues(editor: Editor, request: InsertDialogRequest) {
  const { from, to, empty } = editor.state.selection
  switch (request.kind) {
    case "link":
      return {
        value: (editor.getAttributes("link").href as string | undefined) ?? "",
        text: empty ? "" : editor.state.doc.textBetween(from, to, " "),
      }
    case "image":
      if (request.pos === undefined) return { value: "", text: "" }
      return {
        value: (editor.getAttributes("image").src as string | undefined) ?? "",
        text: (editor.getAttributes("image").alt as string | undefined) ?? "",
      }
    default:
      return { value: request.initial ?? "", text: "" }
  }
}

/**
 * The one dialog behind every insert that needs input: links, images and
 * formulas. Saving writes to the editor and returns focus
 * to where the caret was.
 */
export function InsertDialog({
  editor,
  request,
  ui,
  urlPolicy,
  onClose,
}: {
  editor: Editor
  request: InsertDialogRequest | null
  ui: () => EditorUiHandlers
  urlPolicy: UrlPolicy
  onClose: () => void
}) {
  // Keep the last request while the dialog animates closed.
  const [shown, setShown] = React.useState(request)
  if (request && request !== shown) setShown(request)
  const kind = shown?.kind ?? "link"
  const copy = COPY[kind]
  const editing =
    shown?.pos !== undefined || (kind === "link" && editor.isActive("link"))

  const [value, setValue] = React.useState("")
  const [text, setText] = React.useState("")
  const [error, setError] = React.useState<string | null>(null)
  const [openedFor, setOpenedFor] = React.useState<InsertDialogRequest | null>(
    null
  )
  if (request && request !== openedFor) {
    const initial = initialValues(editor, request)
    setOpenedFor(request)
    setValue(initial.value)
    setText(initial.text)
    setError(null)
  }

  const isMath = kind === "inlineMath" || kind === "blockMath"
  const preview = React.useMemo(
    () =>
      isMath && value.trim()
        ? katex.renderToString(value, {
            throwOnError: false,
            displayMode: kind === "blockMath",
          })
        : "",
    [isMath, kind, value]
  )

  const pos = shown?.pos
  const id = React.useId()
  const chain = () => editor.chain().focus()

  const save = (): string | null => {
    const input = value.trim()
    switch (kind) {
      case "link": {
        const href = normalizeHref(input)
        if (!href) {
          chain().extendMarkRange("link").unsetLink().run()
          return null
        }
        if (!urlPolicy(href, "link")) return "That link isn't allowed."
        if (editor.state.selection.empty && !editor.isActive("link")) {
          return chain()
            .insertContent({
              type: "text",
              text: text.trim() || href,
              marks: [{ type: "link", attrs: { href } }],
            })
            .run()
            ? null
            : "That link isn't allowed."
        }
        return chain().extendMarkRange("link").setLink({ href }).run()
          ? null
          : "That link isn't allowed."
      }
      case "image": {
        if (!urlPolicy(input, "image")) {
          return "Enter an http or https address."
        }
        const alt = text.trim() || null
        if (pos !== undefined) {
          chain()
            .setNodeSelection(pos)
            .updateAttributes("image", { src: input, alt })
            .run()
        } else
          chain()
            .setImage({ src: input, alt: alt ?? undefined })
            .run()
        return null
      }
      case "inlineMath":
        if (pos !== undefined) {
          if (!input) chain().deleteInlineMath({ pos }).run()
          else chain().updateInlineMath({ latex: input, pos }).run()
        } else if (input) chain().insertInlineMath({ latex: input }).run()
        return null
      case "blockMath":
        if (pos !== undefined) {
          if (!input) chain().deleteBlockMath({ pos }).run()
          else chain().updateBlockMath({ latex: input, pos }).run()
        } else if (input) chain().insertBlockMath({ latex: input }).run()
        return null
    }
  }

  const submit = (event: { preventDefault: () => void }) => {
    event.preventDefault()
    const problem = save()
    if (problem) setError(problem)
    else onClose()
  }

  const upload = kind === "image"
  const showText =
    kind === "link" && editor.state.selection.empty && !editor.isActive("link")
  const showAlt = kind === "image"

  return (
    <Dialog open={request !== null} onOpenChange={(open) => !open && onClose()}>
      <DialogContent
        className="sm:max-w-md"
        finalFocus={() => editor.view.dom as HTMLElement}
      >
        <form onSubmit={submit} className="grid gap-5" noValidate>
          <DialogHeader>
            <DialogTitle>
              {editing ? `Edit ${copy.title.toLowerCase()}` : copy.title}
            </DialogTitle>
            <DialogDescription>{copy.description}</DialogDescription>
          </DialogHeader>

          <FieldGroup>
            {upload && pos === undefined && (
              <>
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => {
                    onClose()
                    ui().pickImages()
                  }}
                >
                  <Icon icon={Upload01Icon} data-icon="inline-start" />
                  Upload an image
                </Button>
                <div className="flex items-center gap-3 text-2xs text-muted-foreground before:h-px before:flex-1 before:bg-border after:h-px after:flex-1 after:bg-border">
                  or link one
                </div>
              </>
            )}
            <Field data-invalid={Boolean(error)}>
              <FieldLabel htmlFor={`${id}-value`}>{copy.field}</FieldLabel>
              {isMath ? (
                <Textarea
                  id={`${id}-value`}
                  value={value}
                  placeholder={copy.placeholder}
                  spellCheck={false}
                  aria-invalid={Boolean(error)}
                  onChange={(event) => setValue(event.target.value)}
                  onKeyDown={(event) => {
                    if (
                      event.key === "Enter" &&
                      (event.metaKey || event.ctrlKey)
                    ) {
                      submit(event)
                    }
                  }}
                  className="min-h-20 font-mono text-xs"
                />
              ) : (
                <Input
                  id={`${id}-value`}
                  value={value}
                  placeholder={copy.placeholder}
                  type={kind === "link" ? "text" : "url"}
                  inputMode="url"
                  autoComplete="off"
                  spellCheck={false}
                  aria-invalid={Boolean(error)}
                  onChange={(event) => {
                    setValue(event.target.value)
                    setError(null)
                  }}
                />
              )}
              {isMath && (
                <FieldDescription>
                  {formatShortcut("Mod-Enter")} saves.
                  {pos !== undefined &&
                    " Leave it empty to remove the formula."}
                </FieldDescription>
              )}
              {kind === "link" && editing && (
                <FieldDescription>
                  Leave it empty to remove the link.
                </FieldDescription>
              )}
              {error && <FieldError>{error}</FieldError>}
            </Field>
            {(showText || showAlt) && (
              <Field>
                <FieldLabel htmlFor={`${id}-text`}>
                  {showAlt ? "Alt text" : "Text to show"}
                </FieldLabel>
                <Input
                  id={`${id}-text`}
                  value={text}
                  placeholder={
                    showAlt ? "What the image shows" : "Defaults to the URL"
                  }
                  onChange={(event) => setText(event.target.value)}
                />
                {showAlt && (
                  <FieldDescription>
                    Read aloud by screen readers and shown if the image can't
                    load.
                  </FieldDescription>
                )}
              </Field>
            )}
            {isMath && (
              <div
                aria-label="Preview"
                className="grid min-h-14 place-items-center overflow-x-auto rounded-(--radius-card) border border-border bg-muted/40 px-3 py-2 text-sm"
              >
                {preview ? (
                  <span dangerouslySetInnerHTML={{ __html: preview }} />
                ) : (
                  <span className="text-xs text-subtle">Preview</span>
                )}
              </div>
            )}
          </FieldGroup>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit">{editing ? "Save" : "Insert"}</Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

import * as React from "react"
