import { Skeleton } from "@/components/ui/skeleton"
import type { RichTextEditorProps } from "./rich-text-editor"

// Tiptap, KaTeX, the emoji set and the syntax grammars come to ~500 kB
// gzipped, so the editor loads with the first field that shows it, not with
// every page that could.
const load = () => import("./rich-text-editor")
const Editor = React.lazy(() =>
  load().then((module) => ({ default: module.RichTextEditor }))
)
const View = React.lazy(() =>
  load().then((module) => ({ default: module.RichTextView }))
)

function EditorSkeleton({
  className,
  toolbar,
}: {
  className?: string
  toolbar: boolean
}) {
  return (
    <div
      aria-busy="true"
      aria-label="Loading editor"
      className={cn(
        "flex flex-col rounded-(--radius-control) border border-border bg-background",
        className
      )}
    >
      {toolbar && (
        <div className="flex items-center gap-1.5 border-b border-border px-2 py-2">
          <Skeleton className="h-5 w-12" />
          <Skeleton className="h-5 w-24" />
          <Skeleton className="h-5 w-40" />
        </div>
      )}
      <div className="flex min-h-32 flex-col gap-2 px-4 py-3">
        <Skeleton className="h-4 w-2/3" />
        <Skeleton className="h-4 w-1/2" />
      </div>
    </div>
  )
}

/**
 * The Markdown rich text editor. See `rich-text-editor.tsx` for the props;
 * this wrapper loads it on first render and shows a field skeleton
 * meanwhile. A `ref` gets the controller once it has loaded.
 */
export function RichTextEditor(props: RichTextEditorProps) {
  const editable = !props.readOnly && !props.disabled
  const toolbar =
    !props.headless &&
    (typeof props.toolbar === "boolean"
      ? props.toolbar
      : (props.toolbar?.enabled ?? editable))
  return (
    <React.Suspense
      fallback={
        <EditorSkeleton className={props.className} toolbar={toolbar} />
      }
    >
      <Editor {...props} />
    </React.Suspense>
  )
}

/** Saved Markdown, shown read-only; loads the editor like `RichTextEditor`. */
export function RichTextView(props: React.ComponentProps<typeof View>) {
  return (
    <React.Suspense
      fallback={
        <div aria-busy="true" className="flex flex-col gap-2">
          <Skeleton className="h-4 w-2/3" />
          <Skeleton className="h-4 w-1/2" />
        </div>
      }
    >
      <View {...props} />
    </React.Suspense>
  )
}

import dockerfile from "highlight.js/lib/languages/dockerfile"
import { common, createLowlight } from "lowlight"

/** Highlight.js grammars for code blocks: the common set plus Dockerfiles. */
export const lowlight = createLowlight({ ...common, dockerfile })

import { Extension } from "@tiptap/core"
import { Plugin, PluginKey } from "@tiptap/pm/state"

import { insertableContent, parseMarkdown } from "./core/markdown"
import type { UrlPolicy } from "./types"

// Block syntax at a line start, or inline bold, links and code spans.
const MARKDOWN_HINT =
  /^(?:#{1,6}\s|[-*+]\s|\d+[.)]\s|>\s|```|\|.*\|\s*$|- \[[ x]\]\s)|\*\*[^*\n]+\*\*|\[[^\]\n]+\]\([^)\s]+\)|`[^`\n]+`/m

export interface MarkdownPasteOptions {
  getUrlPolicy: () => UrlPolicy | undefined
  /** Told how many unsafe links and images a paste lost. */
  onUnsafe: (removed: number) => void
}

/**
 * Pasting plain text that looks like Markdown (from an editor, a terminal or
 * a chat) converts it to rich content, through the same parser and URL
 * policy as every other Markdown. Copies that carry HTML paste as HTML,
 * and code blocks keep the text as typed.
 */
export const MarkdownPaste = Extension.create<MarkdownPasteOptions>({
  name: "markdownPaste",

  addOptions() {
    return { getUrlPolicy: () => undefined, onUnsafe: () => {} }
  },

  addProseMirrorPlugins() {
    const editor = this.editor
    const { getUrlPolicy, onUnsafe } = this.options
    return [
      new Plugin({
        key: new PluginKey("markdownPaste"),
        props: {
          handlePaste: (_view, event) => {
            const data = event.clipboardData
            if (
              !data ||
              data.files.length ||
              data.types.includes("text/html")
            ) {
              return false
            }
            const text = data.getData("text/plain")
            if (!text || !MARKDOWN_HINT.test(text)) return false
            if (editor.isActive("codeBlock") || editor.isActive("code")) {
              return false
            }
            const { doc, removed } = parseMarkdown(editor, text, getUrlPolicy())
            if (removed) onUnsafe(removed)
            const { $from, $to } = editor.state.selection
            const inline = $from.parent.isTextblock && $to.parent.isTextblock
            return editor.commands.insertContent(insertableContent(doc, inline))
          },
        },
      }),
    ]
  },
})

import * as React from "react"

import {
  ContextMenuCheckboxItem,
  ContextMenuGroup,
  ContextMenuItem,
  ContextMenuLabel,
  ContextMenuSeparator,
  ContextMenuShortcut,
  ContextMenuSub,
  ContextMenuSubContent,
  ContextMenuSubTrigger,
} from "@/components/ui/context-menu"
import {
  DropdownMenuCheckboxItem,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
} from "@/components/ui/dropdown-menu"
import { Spinner } from "@/components/ui/spinner"
import { ActionIcon } from "./controls"
import { useEditorActions, type ResolvedAction } from "./context"
import { menuActionIds, tidySeparators } from "./menu-model"
import { formatShortcut } from "./shortcuts"
import type { ActionSource, MenuItem } from "./types"

// Dropdown and context menus are the same Base UI menu underneath; these
// tables let one renderer draw either.
const PARTS = {
  dropdown: {
    Item: DropdownMenuItem,
    CheckboxItem: DropdownMenuCheckboxItem,
    Group: DropdownMenuGroup,
    Label: DropdownMenuLabel,
    Separator: DropdownMenuSeparator,
    Shortcut: DropdownMenuShortcut,
    Sub: DropdownMenuSub,
    SubTrigger: DropdownMenuSubTrigger,
    SubContent: DropdownMenuSubContent,
  },
  context: {
    Item: ContextMenuItem,
    CheckboxItem: ContextMenuCheckboxItem,
    Group: ContextMenuGroup,
    Label: ContextMenuLabel,
    Separator: ContextMenuSeparator,
    Shortcut: ContextMenuShortcut,
    Sub: ContextMenuSub,
    SubTrigger: ContextMenuSubTrigger,
    SubContent: ContextMenuSubContent,
  },
}

/**
 * Menu entries for actions, drawn as dropdown or context menu items:
 * hidden actions disappear, disabled ones grey out, toggles show a check,
 * and running ones a spinner.
 */
export function MenuEntries({
  items,
  kind,
  source,
  onRun,
}: {
  items: MenuItem[]
  kind: "dropdown" | "context"
  source: ActionSource
  onRun: (id: string) => void
}) {
  const resolved = useEditorActions(menuActionIds(items), source)
  const byId = new Map(resolved.map((entry) => [entry.id, entry]))
  return <>{renderEntries(items, kind, (id) => byId.get(id), onRun)}</>
}

function renderEntries(
  items: MenuItem[],
  kind: "dropdown" | "context",
  lookup: (id: string) => ResolvedAction | undefined,
  onRun: (id: string) => void
): React.ReactNode[] {
  const P = PARTS[kind]
  type Entry = { separator: true } | { separator: false; node: React.ReactNode }
  const entries: Entry[] = items.flatMap((item, index): Entry[] => {
    if (item === "separator") return [{ separator: true }]
    if (typeof item === "string") {
      const entry = lookup(item)
      if (!entry || !entry.state.visible) return []
      const { action, state } = entry
      const content = (
        <>
          {state.running ? <Spinner /> : <ActionIcon icon={action.icon} />}
          {action.label}
          {action.shortcut && (
            <P.Shortcut>{formatShortcut(action.shortcut)}</P.Shortcut>
          )}
        </>
      )
      return [
        {
          separator: false,
          node: action.isActive ? (
            <P.CheckboxItem
              key={action.id}
              checked={state.active}
              disabled={!state.enabled}
              closeOnClick
              onCheckedChange={() => onRun(action.id)}
            >
              {content}
            </P.CheckboxItem>
          ) : (
            <P.Item
              key={action.id}
              disabled={!state.enabled}
              onClick={() => onRun(action.id)}
            >
              {content}
            </P.Item>
          ),
        },
      ]
    }
    const children = renderEntries(item.items, kind, lookup, onRun)
    if (!children.length) return []
    if (item.type === "group") {
      return [
        {
          separator: false,
          node: (
            <P.Group key={`group-${index}`}>
              <P.Label>{item.label}</P.Label>
              {children}
            </P.Group>
          ),
        },
      ]
    }
    return [
      {
        separator: false,
        node: (
          <P.Sub key={`sub-${index}`}>
            <P.SubTrigger>
              <ActionIcon icon={item.icon} />
              {item.label}
            </P.SubTrigger>
            <P.SubContent className="min-w-48">{children}</P.SubContent>
          </P.Sub>
        ),
      },
    ]
  })
  return tidySeparators(entries).map((entry, index) =>
    entry.separator ? <P.Separator key={`separator-${index}`} /> : entry.node
  )
}

