import type { Editor } from "@tiptap/core"
import { TextSelection } from "@tiptap/pm/state"

import { AIController } from "./ai/ai-controller"
import { ActionRegistry } from "./core/action-registry"
import { createEditorController } from "./core/editor-controller"
import { isAlive } from "./core/lifecycle"
import { parseMarkdown, serializeMarkdown } from "./core/markdown"
import { MarkdownSync } from "./core/markdown-sync"
import { defaultUrlPolicy } from "./core/security"
import type { EditorHandlers } from "./extensions"
import { insertFiles } from "./files"
import type {
  EditorController,
  EditorError,
  EditorUiHandlers,
  UrlPolicy,
} from "./types"
import type { UseRichTextEditorOptions } from "./use-rich-text-editor"

const DEFAULT_MAX_FILE_SIZE = 10 * 1024 * 1024

const unsafeMessage = (removed: number) =>
  `Removed ${removed} link or image URL${removed === 1 ? "" : "s"} the editor doesn't allow.`

/**
 * What outlives renders and rebuilt Tiptap instances: the controller, the
 * action registry, AI and the controlled-value sync. Every callback reads
 * the options of the latest render, so nothing is rebuilt for a new prop.
 */
export class EditorRuntime {
  private options: UseRichTextEditorOptions
  private editor: Editor | null = null
  private readyNotified = false
  readonly registry: ActionRegistry
  readonly controller: EditorController
  readonly ai: AIController
  readonly sync: MarkdownSync
  readonly handlers: EditorHandlers

  constructor(options: UseRichTextEditorOptions) {
    this.options = options
    this.registry = new ActionRegistry(this.onError)
    this.controller = createEditorController({
      getEditor: () => this.editor,
      registry: this.registry,
      getUrlPolicy: () => this.options.urlPolicy,
      getAI: () => (this.options.ai?.enabled ? this.ai : null),
      onError: this.onError,
    })
    this.ai = new AIController({
      controller: this.controller,
      getEditor: () => this.editor,
      getConfig: () => this.options.ai,
      onError: this.onError,
    })
    this.sync = new MarkdownSync({
      initial: options.value ?? options.defaultValue ?? "",
      read: () => this.currentContent(""),
      emit: (markdown) => this.options.onChange?.(markdown),
      delay: () => this.options.onChangeDebounce ?? 0,
    })
    this.handlers = {
      ui: this.ui,
      registry: this.registry,
      controller: this.controller,
      insertFiles: (editor, files, pos) =>
        void insertFiles(editor, files, {
          upload: this.options.onUpload,
          maxFileSize: this.options.maxFileSize ?? DEFAULT_MAX_FILE_SIZE,
          pos,
          urlPolicy: this.policy(),
          onError: (message) =>
            this.onError({ code: "upload-failed", message }),
        }),
      placeholder: () => this.options.placeholder ?? "Write something…",
      mentions: (query, signal) => this.options.mentions?.(query, signal) ?? [],
      urlPolicy: () => this.options.urlPolicy,
      onUnsafeContent: (removed) =>
        this.onError({
          code: "unsafe-content",
          message: unsafeMessage(removed),
        }),
    }
  }

  /** Called after every render with that render's options. */
  setOptions(options: UseRichTextEditorOptions) {
    this.options = options
  }

  /** Called as each Tiptap instance is created. */
  setEditor(editor: Editor) {
    this.editor = editor
  }

  onError = (error: EditorError) => {
    if (this.options.onError) this.options.onError(error)
    else console.warn(`[RichTextEditor] ${error.message}`)
  }

  policy = (): UrlPolicy => this.options.urlPolicy ?? defaultUrlPolicy

  /** The component's UI, with simple fallbacks for a headless editor. */
  ui = (): EditorUiHandlers => ({
    openDialog: (request) => {
      // Without dialogs, a link falls back to the browser's prompt.
      const editor = this.editor
      if (request.kind !== "link" || !editor || typeof window === "undefined") {
        return
      }
      const current = String(editor.getAttributes("link").href ?? "")
      const href = window.prompt("Link URL", current)
      if (href === null) return
      const chain = editor.chain().focus().extendMarkRange("link")
      if (href.trim()) chain.setLink({ href: href.trim() }).run()
      else chain.unsetLink().run()
    },
    pickImages: () => {},
    toggleFind: () => {},
    toggleOutline: () => {},
    toggleFullscreen: () => {},
    toggleFocusMode: () => {},
    askAI: () => {},
    viewState: () => ({
      find: false,
      outline: false,
      fullscreen: false,
      focusMode: false,
    }),
    ...this.options.ui,
  })

  /** The document now, or `fallback` before there's an editor. */
  currentContent(fallback: string) {
    return isAlive(this.editor) ? serializeMarkdown(this.editor) : fallback
  }

  /** `onReady`, once per component however often the editor is rebuilt. */
  notifyReady() {
    if (this.readyNotified) return
    this.readyNotified = true
    this.options.onReady?.(this.controller)
  }

  focused() {
    this.options.onFocus?.()
  }

  blurred() {
    this.sync.flush()
    this.options.onBlur?.()
  }

  selectionChanged() {
    this.options.onSelectionChange?.(this.controller.getSelection())
  }

  /**
   * A controlled `value` arrived: unless it's our own echo, it replaces the
   * document, outside undo history and without firing `onChange`, keeping
   * the caret where the new text allows.
   */
  receive(editor: Editor, markdown: string) {
    if (!this.sync.received(markdown)) return
    const { doc, removed } = parseMarkdown(editor, markdown, this.policy())
    if (removed) {
      this.onError({ code: "unsafe-content", message: unsafeMessage(removed) })
    }
    let node
    try {
      node = editor.schema.nodeFromJSON(doc)
    } catch (cause) {
      this.onError({
        code: "invalid-props",
        message: "The value doesn't fit this editor's features.",
        cause,
      })
      return
    }
    const { from, to } = editor.state.selection
    const tr = editor.state.tr.replaceWith(
      0,
      editor.state.doc.content.size,
      node.content
    )
    const size = tr.doc.content.size
    tr.setSelection(
      TextSelection.between(
        tr.doc.resolve(Math.min(from, size)),
        tr.doc.resolve(Math.min(to, size))
      )
    )
    tr.setMeta("addToHistory", false).setMeta("preventUpdate", true)
    editor.view.dispatch(tr)
  }

  /** Unmounting: send an edit still waiting in the debounce, stop AI. */
  dispose() {
    this.sync.flush()
    this.sync.dispose()
    this.ai.cancel()
  }
}

const IS_MAC =
  typeof navigator !== "undefined" &&
  /Mac|iPhone|iPad|iPod/.test(navigator.platform || navigator.userAgent)

const MAC_KEYS: Record<string, string> = {
  Mod: "⌘",
  Alt: "⌥",
  Shift: "⇧",
  Ctrl: "⌃",
}

const OTHER_KEYS: Record<string, string> = {
  Mod: "Ctrl",
  Alt: "Alt",
  Shift: "Shift",
  Ctrl: "Ctrl",
}

/**
 * Turns a Tiptap key binding (`Mod-Shift-x`) into what the person presses:
 * `⌘⇧X` on Apple devices, `Ctrl+Shift+X` elsewhere.
 */
export function formatShortcut(binding: string) {
  const keys = IS_MAC ? MAC_KEYS : OTHER_KEYS
  const parts = binding
    .split("-")
    .map(
      (part) => keys[part] ?? (part.length === 1 ? part.toUpperCase() : part)
    )
  return parts.join(IS_MAC ? "" : "+")
}

import { Extension } from "@tiptap/core"
import { PluginKey } from "@tiptap/pm/state"
import { Suggestion } from "@tiptap/suggestion"

import { Kbd } from "@/components/ui/kbd"
import { ActionIcon } from "./controls"
import {
  createActionContext,
  type ActionRegistry,
} from "./core/action-registry"
import { formatShortcut } from "./shortcuts"
import { suggestionRenderer } from "./suggestion"
import type { EditorAction, EditorController } from "./types"

const SlashCommandPluginKey = new PluginKey("slashCommand")

export interface SlashCommandOptions {
  registry: ActionRegistry
  controller: EditorController
}

/** Matches a `/` query against labels and keywords, best matches first. */
export function filterActions(actions: EditorAction[], query: string) {
  const q = query.trim().toLowerCase()
  if (!q) return actions
  const score = (action: EditorAction) => {
    const label = action.label.toLowerCase()
    if (label.startsWith(q)) return 0
    if (label.split(/\s+/).some((word) => word.startsWith(q))) return 1
    if (action.keywords?.some((keyword) => keyword.startsWith(q))) return 2
    if (label.includes(q)) return 3
    return -1
  }
  return actions
    .map((action) => ({ action, score: score(action) }))
    .filter(({ score }) => score >= 0)
    .sort((a, b) => a.score - b.score)
    .map(({ action }) => action)
}

/**
 * Typing `/` opens a filterable menu of every action that offers itself
 * there (`slashCommand`): the built-in blocks, AI and the app's own.
 */
export const SlashCommand = Extension.create<SlashCommandOptions>({
  name: "slashCommand",

  addOptions() {
    return {
      registry: null as unknown as ActionRegistry,
      controller: null as unknown as EditorController,
    }
  },

  addProseMirrorPlugins() {
    const { registry, controller } = this.options
    return [
      Suggestion<EditorAction, EditorAction>({
        editor: this.editor,
        pluginKey: SlashCommandPluginKey,
        char: "/",
        // Not inside code, where `/` is just a character.
        allow: ({ editor }) =>
          !editor.isActive("codeBlock") && !editor.isActive("code"),
        items: ({ query }) => {
          const context = createActionContext(controller, "slash")
          const offered = registry.list().filter((action) => {
            if (!action.slashCommand) return false
            const state = registry.state(action.id, context)
            return state.visible && state.enabled
          })
          return filterActions(offered, query)
        },
        command: ({ editor, range, props: action }) => {
          editor.chain().focus().deleteRange(range).run()
          void registry.run(action.id, createActionContext(controller, "slash"))
        },
        render: suggestionRenderer<EditorAction>({
          label: "Insert block",
          empty: "No matching blocks",
          getKey: (action) => action.id,
          getGroup: (action) => action.group,
          renderItem: (action) => (
            <>
              <span className="grid size-7 place-items-center rounded-(--radius-item) border border-border bg-background text-muted-foreground">
                <ActionIcon icon={action.icon} size={15} />
              </span>
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="truncate text-foreground">{action.label}</span>
                {action.description && (
                  <span className="truncate text-2xs text-muted-foreground">
                    {action.description}
                  </span>
                )}
              </span>
              {action.shortcut && (
                <Kbd variant="ghost">{formatShortcut(action.shortcut)}</Kbd>
              )}
            </>
          ),
        }),
      }),
    ]
  },
})

import { useEditorState } from "@tiptap/react"
import { cn } from "cn"

import { useRichTextEditorContext } from "./context"
import { isAlive } from "./core/lifecycle"

/** Words and characters under the text, and the limit when there is one. */
export function EditorStatusBar({
  maxLength,
  className,
}: {
  maxLength?: number
  className?: string
}) {
  const { editor } = useRichTextEditorContext()
  const count = useEditorState({
    editor,
    selector: ({ editor }) =>
      isAlive(editor) && editor.storage.characterCount
        ? {
            characters: editor.storage.characterCount.characters(),
            words: editor.storage.characterCount.words(),
          }
        : null,
  })
  if (!count) return null
  const near = maxLength !== undefined && count.characters >= maxLength * 0.9
  return (
    <div
      data-slot="rich-text-count"
      className={cn(
        "flex items-center justify-end gap-3 border-t border-border px-3 py-1 text-2xs text-subtle tabular-nums",
        className
      )}
    >
      <span>
        {count.words} {count.words === 1 ? "word" : "words"}
      </span>
      <span
        aria-live={near ? "polite" : undefined}
        className={cn(near && "text-destructive")}
      >
        {maxLength !== undefined
          ? `${count.characters} / ${maxLength} characters`
          : `${count.characters} ${count.characters === 1 ? "character" : "characters"}`}
      </span>
    </div>
  )
}

import * as React from "react"
import type { SuggestionProps } from "@tiptap/suggestion"
import { cn } from "cn"

import { Spinner } from "@/components/ui/spinner"

/** How one kind of suggestion (commands, mentions, emoji) lists its items. */
export interface SuggestionView<I> {
  /** Names the list for screen readers. */
  label: string
  /** Shown when the query matches nothing. */
  empty: string
  getKey: (item: I) => string
  getGroup?: (item: I) => string | undefined
  renderItem: (item: I) => React.ReactNode
}

export interface SuggestionMenuHandle {
  onKeyDown: (event: KeyboardEvent) => boolean
}

export type SuggestionMenuProps = SuggestionProps<unknown, unknown> & {
  view: SuggestionView<unknown>
  ref?: React.Ref<SuggestionMenuHandle>
}

/**
 * The popup under `/`, `@` and `:`. Focus stays in the editor, so the arrow
 * keys, Enter and Tab reach it through `onKeyDown`; the pointer works too.
 */
export function SuggestionMenu({
  items,
  command,
  query,
  loading,
  view,
  ref,
}: SuggestionMenuProps) {
  const [active, setActive] = React.useState(0)
  const listRef = React.useRef<HTMLDivElement>(null)
  const id = React.useId()

  // A new query starts at the top of the new results.
  const [shownItems, setShownItems] = React.useState(items)
  if (shownItems !== items) {
    setShownItems(items)
    setActive(0)
  }

  React.useEffect(() => {
    listRef.current
      ?.querySelector(`[data-index="${active}"]`)
      ?.scrollIntoView({ block: "nearest" })
  }, [active])

  const select = (index: number) => {
    const item = items[index]
    if (item !== undefined) command(item)
  }

  React.useImperativeHandle(ref, () => ({
    onKeyDown: (event) => {
      if (!items.length) return false
      if (event.key === "ArrowDown") {
        setActive((index) => (index + 1) % items.length)
        return true
      }
      if (event.key === "ArrowUp") {
        setActive((index) => (index - 1 + items.length) % items.length)
        return true
      }
      if (event.key === "Enter" || event.key === "Tab") {
        select(active)
        return true
      }
      return false
    },
  }))

  let previousGroup: string | undefined
  return (
    <div
      ref={listRef}
      role="listbox"
      aria-label={view.label}
      data-slot="rich-text-suggestions"
      className="max-h-80 w-64 overflow-y-auto overscroll-contain rounded-(--radius-band) border border-border bg-popover p-1 text-popover-foreground shadow-(--shadow-float)"
    >
      {loading && !items.length ? (
        <div className="flex items-center gap-2 px-2 py-1.5 text-xs text-muted-foreground">
          <Spinner className="size-3.5" />
          Searching…
        </div>
      ) : !items.length ? (
        <div className="px-2 py-1.5 text-xs text-muted-foreground">
          {view.empty}
        </div>
      ) : (
        items.map((item, index) => {
          // Groups while browsing; a query ranks across them instead.
          const group = query ? undefined : view.getGroup?.(item)
          const heading = group !== previousGroup ? group : undefined
          previousGroup = group
          return (
            <React.Fragment key={view.getKey(item)}>
              {heading && (
                <div
                  role="presentation"
                  className="px-2 pt-2 pb-1 text-2xs text-muted-foreground first:pt-1"
                >
                  {heading}
                </div>
              )}
              <div
                id={`${id}-${index}`}
                role="option"
                aria-selected={index === active}
                data-index={index}
                data-active={index === active || undefined}
                // Keep the caret in the editor.
                onMouseDown={(event) => event.preventDefault()}
                onMouseMove={() => index !== active && setActive(index)}
                onClick={() => select(index)}
                className={cn(
                  "flex min-h-8 cursor-default items-center gap-2 rounded-(--radius-item) px-2 py-1.5 text-xs select-none data-active:bg-accent data-active:text-accent-foreground",
                  "[&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4"
                )}
              >
                {view.renderItem(item)}
              </div>
            </React.Fragment>
          )
        })
      )}
    </div>
  )
}

import { ReactRenderer } from "@tiptap/react"
import type { SuggestionOptions } from "@tiptap/suggestion"

import {
  SuggestionMenu,
  type SuggestionMenuHandle,
  type SuggestionMenuProps,
  type SuggestionView,
} from "./suggestion-menu"

/**
 * The `render` option for a Tiptap suggestion: mounts `SuggestionMenu` next
 * to the caret and lets the plugin keep it positioned.
 */
export function suggestionRenderer<I>(
  view: SuggestionView<I>
): SuggestionOptions<I, I>["render"] {
  return () => {
    let renderer: ReactRenderer<
      SuggestionMenuHandle,
      SuggestionMenuProps
    > | null = null
    let unmount: (() => void) | undefined

    return {
      onStart: (props) => {
        renderer = new ReactRenderer(SuggestionMenu, {
          props: { ...props, view },
          editor: props.editor,
          className: "z-50",
        })
        unmount = props.mount(renderer.element as HTMLElement)
      },
      onUpdate: (props) => renderer?.updateProps({ ...props, view }),
      onKeyDown: ({ event }) => renderer?.ref?.onKeyDown(event) ?? false,
      onExit: () => {
        unmount?.()
        renderer?.destroy()
        renderer = null
      },
    }
  }
}

import * as React from "react"
import { SparklesIcon } from "@hugeicons/core-free-icons"
import { cn } from "cn"

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuShortcut,
} from "@/components/ui/dropdown-menu"
import {
  ToolbarAction,
  ToolbarMenuTrigger,
  ToolbarSeparator,
  ToolbarToggle,
} from "./controls"
import {
  useEditorActions,
  useRichTextEditorContext,
  useRunAction,
  type ResolvedAction,
} from "./context"
import { MenuEntries } from "./menu-items"
import {
  TOOLBAR_WIDGETS,
  defaultToolbarItems,
  menuActionIds,
  tidySeparators,
} from "./menu-model"
import { formatShortcut } from "./shortcuts"
import type { EditorAction, MenuItem, ToolbarItem } from "./types"

const BLOCK_TYPES = [
  "paragraph",
  "heading1",
  "heading2",
  "heading3",
  "heading4",
  "heading5",
  "heading6",
  "blockquote",
  "codeBlock",
]

const MORE_ITEMS: MenuItem[] = [
  { type: "group", label: "View", items: ["focusMode", "invisibleCharacters"] },
  "separator",
  {
    type: "group",
    label: "Export",
    items: ["copyMarkdown", "downloadMarkdown"],
  },
]

/** Every action id a toolbar mentions, menus included. */
function toolbarIds(items: ToolbarItem[]): string[] {
  return items.flatMap((item) => {
    if (typeof item !== "string") {
      return item.type === "group"
        ? toolbarIds(item.items)
        : menuActionIds(item.items)
    }
    if (item === "heading" || item === "blockType") return BLOCK_TYPES
    return TOOLBAR_WIDGETS.has(item) ? [] : [item]
  })
}

/** The `/` menu's actions, grouped, for the Insert menu. */
function insertMenu(actions: EditorAction[]): MenuItem[] {
  const groups = new Map<string, string[]>()
  for (const action of actions) {
    if (!action.slashCommand) continue
    const group = action.group ?? "More"
    groups.set(group, [...(groups.get(group) ?? []), action.id])
  }
  return [...groups].flatMap(([label, items], index): MenuItem[] => [
    ...(index > 0 ? ["separator"] : []),
    { type: "group", label, items },
  ])
}

/**
 * The formatting toolbar, drawn from `items`: action ids become buttons
 * (toggles when the action has a pressed state), plus the block type,
 * Insert, AI and More menus. Every button runs through the action registry,
 * so it does what the same id does in menus, `/` and code.
 */
export function EditorToolbar({
  items,
  position = "top",
  className,
  label = "Formatting",
}: {
  items?: ToolbarItem[]
  position?: "top" | "bottom"
  className?: string
  label?: string
}) {
  const { editor, registry, features } = useRichTextEditorContext()
  const all = registry.list()
  const aiIds = all.filter((a) => a.id.startsWith("ai.")).map((a) => a.id)
  const list = items ?? defaultToolbarItems(features, aiIds.length > 0)
  const resolved = useEditorActions(toolbarIds(list))
  const byId = new Map(resolved.map((entry) => [entry.id, entry]))
  const run = useRunAction("toolbar")
  // Menus hand focus back to the text, not their trigger, so typing goes on.
  const toEditor = () => editor.view.dom as HTMLElement
  const editable = editor.isEditable

  const menu = (
    key: string,
    trigger: React.ReactNode,
    entries: MenuItem[],
    align: "start" | "end" = "start"
  ) => (
    <DropdownMenu key={key}>
      {trigger}
      <DropdownMenuContent
        finalFocus={toEditor}
        align={align}
        className="max-h-96 min-w-56"
      >
        <MenuEntries
          items={entries}
          kind="dropdown"
          source="toolbar"
          onRun={run}
        />
      </DropdownMenuContent>
    </DropdownMenu>
  )

  const render = (
    item: ToolbarItem,
    index: number
  ): { separator: boolean; node?: React.ReactNode }[] => {
    if (item === "separator") return [{ separator: true }]
    if (item === "spacer") {
      return [
        {
          separator: false,
          node: <span key={`spacer-${index}`} aria-hidden className="flex-1" />,
        },
      ]
    }
    if (item === "heading" || item === "blockType") {
      const options = BLOCK_TYPES.flatMap((id) => {
        const entry = byId.get(id)
        return entry?.state.visible ? [entry] : []
      })
      if (options.length < 2) return []
      return [
        {
          separator: false,
          node: (
            <BlockTypeMenu
              key="block-type"
              options={options}
              onSelect={run}
              toEditor={toEditor}
            />
          ),
        },
      ]
    }
    if (item === "insert") {
      const entries = insertMenu(all)
      if (!entries.length) return []
      return [
        {
          separator: false,
          node: menu(
            "insert",
            <ToolbarMenuTrigger
              icon="plus"
              label="Insert"
              value="Insert"
              disabled={!editable}
            />,
            entries
          ),
        },
      ]
    }
    if (item === "ai") {
      if (!aiIds.length) return []
      return [
        {
          separator: false,
          node: menu(
            "ai",
            <ToolbarMenuTrigger
              icon={SparklesIcon}
              label="AI"
              value="AI"
              disabled={!editable}
            />,
            aiIds
          ),
        },
      ]
    }
    if (item === "more") {
      return [
        {
          separator: false,
          node: menu(
            "more",
            <ToolbarMenuTrigger icon="more" label="More" className="px-1" />,
            MORE_ITEMS,
            "end"
          ),
        },
      ]
    }
    if (typeof item !== "string") {
      if (item.type === "menu") {
        return [
          {
            separator: false,
            node: menu(
              `menu-${index}`,
              <ToolbarMenuTrigger
                icon={item.icon}
                label={item.label}
                value={item.icon ? undefined : item.label}
              />,
              item.items
            ),
          },
        ]
      }
      const children = tidySeparators(item.items.flatMap(render))
      if (!children.some((child) => !child.separator)) return []
      return [
        {
          separator: false,
          node: (
            <div
              key={`group-${index}`}
              role="group"
              aria-label={item.label}
              className="flex items-center gap-0.5"
            >
              {children.map((child, i) =>
                child.separator ? <ToolbarSeparator key={i} /> : child.node
              )}
            </div>
          ),
        },
      ]
    }
    const entry = byId.get(item)
    if (!entry?.state.visible) return []
    return [
      {
        separator: false,
        node: <ActionControl key={item} entry={entry} onRun={run} />,
      },
    ]
  }

  const entries = tidySeparators(list.flatMap(render))

  return (
    <div
      role="toolbar"
      aria-label={label}
      aria-orientation="horizontal"
      data-slot="rich-text-toolbar"
      data-position={position}
      className={cn(
        "z-10 flex flex-wrap items-center gap-0.5 bg-background px-1.5 py-1",
        position === "top"
          ? "sticky top-0 rounded-t-[inherit] border-b border-border"
          : "rounded-b-[inherit] border-t border-border",
        className
      )}
    >
      {entries.map((entry, index) =>
        entry.separator ? (
          <ToolbarSeparator key={`separator-${index}`} />
        ) : (
          entry.node
        )
      )}
    </div>
  )
}

/** One action as a toolbar button: a toggle when it can be pressed. */
function ActionControl({
  entry,
  onRun,
}: {
  entry: ResolvedAction
  onRun: (id: string) => void
}) {
  const { action, state } = entry
  if (action.isActive) {
    return (
      <ToolbarToggle
        icon={action.icon}
        label={action.label}
        shortcut={action.shortcut}
        pressed={state.active}
        disabled={!state.enabled}
        onPressedChange={() => onRun(action.id)}
      />
    )
  }
  return (
    <ToolbarAction
      icon={action.icon}
      label={action.label}
      shortcut={action.shortcut}
      disabled={!state.enabled}
      busy={state.running}
      onClick={() => onRun(action.id)}
    />
  )
}

/** Text, headings, quote and code block, showing what the caret is in. */
function BlockTypeMenu({
  options,
  onSelect,
  toEditor,
}: {
  options: ResolvedAction[]
  onSelect: (id: string) => void
  toEditor: () => HTMLElement
}) {
  // The most specific block wins: a heading inside a quote shows the heading.
  const current =
    options.find(
      (o) => o.id !== "paragraph" && o.id !== "blockquote" && o.state.active
    ) ??
    options.find((o) => o.id === "blockquote" && o.state.active) ??
    options.find((o) => o.id === "paragraph")
  const disabled = !options.some((option) => option.state.enabled)
  return (
    <DropdownMenu>
      <ToolbarMenuTrigger
        label="Block type"
        value={current?.action.label ?? "Text"}
        disabled={disabled}
        className="w-[6.75rem] justify-between"
      />
      <DropdownMenuContent finalFocus={toEditor} className="min-w-44">
        <DropdownMenuRadioGroup
          value={current?.id ?? "paragraph"}
          onValueChange={(value) => {
            if (value !== current?.id) onSelect(String(value))
          }}
        >
          {options.map(({ id, action, state }) => (
            <DropdownMenuRadioItem
              key={id}
              value={id}
              disabled={!state.enabled && !state.active}
            >
              <span
                className={
                  id.startsWith("heading")
                    ? "font-semibold"
                    : id === "codeBlock"
                      ? "font-mono"
                      : undefined
                }
              >
                {action.label}
              </span>
              {action.shortcut && (
                <DropdownMenuShortcut>
                  {formatShortcut(action.shortcut)}
                </DropdownMenuShortcut>
              )}
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

import type * as React from "react"
import type { AnyExtension, Editor } from "@tiptap/core"

import type { IconProp } from "../icons"
import type { EditorAIConfig } from "./ai/ai-types.ts"

/**
 * The optional parts of the editor. Each one adds its extension, toolbar and
 * menu entries, `/` commands and Markdown rules; a disabled one is gone from
 * all of them, and Markdown that uses it stays as literal text.
 */
export interface EditorFeatures {
  // Inline formatting
  bold?: boolean
  italic?: boolean
  /** `++underline++` in Markdown. */
  underline?: boolean
  strike?: boolean
  inlineCode?: boolean
  /** `==highlight==` in Markdown. */
  highlight?: boolean
  /** `<sub>` and `<sup>` in Markdown. */
  subscript?: boolean
  superscript?: boolean
  links?: boolean

  // Blocks
  /** H1–H6. */
  headings?: boolean
  blockquote?: boolean
  orderedList?: boolean
  bulletList?: boolean
  /** `- [ ]` checklists. */
  taskList?: boolean
  /** Fenced code blocks. */
  codeBlock?: boolean
  /** Syntax colours and a language picker in code blocks. */
  codeHighlighting?: boolean
  horizontalRule?: boolean
  /** GFM tables (one paragraph per cell, no merged cells). */
  tables?: boolean
  /** `![alt](url)` images by URL, upload, paste or drop. */
  images?: boolean
  /** `$inline$` and `$$block$$` KaTeX formulas. */
  math?: boolean

  // Editing behaviour
  /** Undo and redo. */
  history?: boolean
  /** Typing Markdown (`# `, `- `, `**bold**`) formats as you go. */
  markdownShortcuts?: boolean
  /** The `/` command menu. */
  slashCommands?: boolean
  /** Word and character counts under the text. */
  characterCount?: boolean
  /** `:shortcode:` emoji suggestions (saved as the emoji character). */
  emoji?: boolean
  /** Smart quotes, dashes and arrows as you type. */
  typography?: boolean

  // Tools
  /** The handle beside blocks, for dragging and the block menu. */
  dragHandle?: boolean
  /** ⌘F find and replace. Off by default: it takes over the browser's find. */
  findReplace?: boolean
  /** The outline (table of contents) panel. */
  outline?: boolean
  invisibleCharacters?: boolean
  /** ⌘⇧Enter full-screen editing. */
  fullscreen?: boolean
}

export type ResolvedEditorFeatures = Required<EditorFeatures>

/**
 * Starting points for `features`: `standard` is basic formatting, headings,
 * lists, links, quotes, code and history; `full` turns everything on;
 * `minimal` suits a comment box.
 */
export type EditorPreset = "minimal" | "standard" | "full"

/** Document-model positions (not Markdown character offsets). */
export interface EditorRange {
  from: number
  to: number
}

export interface EditorSelection extends EditorRange {
  /** The selected text, blocks separated by newlines. */
  text: string
  empty: boolean
}

export type EditorErrorCode =
  | "action-failed"
  | "unknown-action"
  | "read-only"
  | "invalid-range"
  | "invalid-props"
  | "unsafe-content"
  | "clipboard"
  | "upload-failed"
  | "ai-failed"
  | "ai-target-changed"

export interface EditorError {
  code: EditorErrorCode
  message: string
  actionId?: string
  cause?: unknown
}

/** Where an action was started from. */
export type ActionSource =
  "toolbar" | "contextMenu" | "bubbleMenu" | "slash" | "shortcut" | "api"

/**
 * An immutable snapshot taken when an action starts (for menus, when the menu
 * opened), so the action works on what the person had selected then.
 */
export interface EditorActionContext {
  editor: EditorController
  selection: EditorSelection
  selectedText: string
  /** Serialized on first read. */
  documentMarkdown: string
  readOnly: boolean
  source: ActionSource
}

/**
 * A command the toolbar, menus, `/` menu, shortcuts and code can all run by
 * id. Registering one with a built-in's id replaces the built-in.
 */
export interface EditorAction {
  id: string
  label: string
  /** A React node, a Forge icon name or a Hugeicons glyph. */
  icon?: React.ReactNode | IconProp
  /** Groups entries in the `/` menu and the toolbar's Insert menu. */
  group?: string
  /** A second line in the `/` menu. */
  description?: string
  /** Extra words the `/` menu matches. */
  keywords?: string[]
  /** A Tiptap key binding (`Mod-Shift-u`): shown in menus and bound in the editor. */
  shortcut?: string
  /** Offer the action in the `/` menu. */
  slashCommand?: boolean
  /** Run it in read-only mode too. Off by default, so read-only rejects it. */
  allowReadOnly?: boolean
  isVisible?: (context: EditorActionContext) => boolean
  isEnabled?: (context: EditorActionContext) => boolean
  /** Shows the action pressed (a toggle), like bold inside bold text. */
  isActive?: (context: EditorActionContext) => boolean
  execute: (context: EditorActionContext) => void | Promise<void>
}

/** Options for the content methods. */
export interface ContentOptions {
  /** Keep the change out of undo history. Default false. */
  skipHistory?: boolean
  /** Apply even in read-only mode. Default false. */
  ignoreReadOnly?: boolean
}

/** A range that follows edits made after it was taken. */
export interface EditorBookmark {
  id: string
  /** The range now, or null when its text changed or was deleted. */
  resolve: () => EditorRange | null
  release: () => void
}

/**
 * Imperative access to the editor, through `ref` or `onReady`. Content goes
 * in and out as Markdown; ranges are document positions. The editing methods
 * return false (and report `read-only` through `onError`) in read-only mode.
 */
export interface EditorController {
  getMarkdown(): string
  setMarkdown(markdown: string, options?: ContentOptions): boolean
  clear(options?: ContentOptions): boolean

  /** At the caret, replacing the selection if there is one. */
  insertMarkdown(markdown: string, options?: ContentOptions): boolean
  /** As new blocks at the end of the document. */
  appendMarkdown(markdown: string, options?: ContentOptions): boolean
  replaceSelection(markdown: string, options?: ContentOptions): boolean
  replaceRange(
    range: EditorRange,
    markdown: string,
    options?: ContentOptions
  ): boolean

  getSelection(): EditorSelection
  getSelectedText(): string
  getSelectedMarkdown(): string
  setSelection(range: EditorRange): void
  /** A range that follows later edits, for async work such as AI. */
  bookmark(range?: EditorRange): EditorBookmark

  /** Focuses the text: at `position`, or back at the selection. */
  focus(position?: "start" | "end" | "all" | number): void
  blur(): void
  undo(): boolean
  redo(): boolean
  canUndo(): boolean
  canRedo(): boolean
  isEmpty(): boolean
  isReadOnly(): boolean

  executeAction(id: string, source?: ActionSource): Promise<void>
  /** Adds an action at runtime; returns a function that removes it. */
  registerAction(action: EditorAction): () => void
  getActions(): EditorAction[]

  /** Runs an AI action (`rewrite` or `ai.rewrite`). */
  runAI(actionId: string, options?: { instruction?: string }): Promise<void>
  cancelAI(): void

  /** The Tiptap editor, for anything the controller doesn't cover. */
  getTiptapEditor(): Editor | null
}

/** A toolbar or bubble menu entry. */
export type ToolbarItem =
  /**
   * An action id (`"bold"`, `"ai.rewrite"`, a custom one), `"separator"`,
   * `"spacer"` (pushes what follows to the end), or a built-in control:
   * `"heading"` (block type), `"insert"`, `"ai"` (AI menu), `"more"`.
   */
  | string
  /** A labelled cluster of items. */
  | { type: "group"; label: string; items: ToolbarItem[] }
  /** A dropdown of actions. */
  | {
      type: "menu"
      label: string
      icon?: React.ReactNode | IconProp
      items: MenuItem[]
    }

export interface ToolbarConfig {
  /** Defaults to on while the editor is editable. */
  enabled?: boolean
  position?: "top" | "bottom"
  /** Defaults to a set that follows the enabled features. */
  items?: ToolbarItem[]
  className?: string
}

/** A context menu entry. */
export type MenuItem =
  /** An action id, `"separator"`, or `"ai"` (a submenu of AI actions). */
  | string
  | {
      type: "submenu"
      label: string
      icon?: React.ReactNode | IconProp
      items: MenuItem[]
    }
  | { type: "group"; label: string; items: MenuItem[] }

export interface ContextMenuConfig {
  /** Defaults to on; off leaves the browser's own menu. */
  enabled?: boolean
  items?: MenuItem[]
}

export interface BubbleMenuConfig {
  /** The selection, link, table and image menus. Defaults to on. */
  enabled?: boolean
  /** What the selection menu shows. */
  items?: ToolbarItem[]
}

/** A person, agent or thing that can be @-mentioned. */
export interface MentionItem {
  id: string
  label: string
  /** A secondary line in the suggestion list (email, role, …). */
  description?: string
}

/** Returns the mention candidates for a query (what follows the `@`). */
export type MentionSource = (
  query: string,
  signal: AbortSignal
) => MentionItem[] | Promise<MentionItem[]>

/**
 * Stores a file the person added (picked, pasted or dropped) and returns the
 * URL to reference. Without it, images are embedded as data URLs.
 */
export type UploadHandler = (file: File) => Promise<string>

/** Which URLs links and images may use. */
export type UrlPolicy = (url: string, kind: "link" | "image") => boolean

/** The dialogs the editor opens to collect a URL or formula. */
export type InsertDialogKind = "link" | "image" | "inlineMath" | "blockMath"

export interface InsertDialogRequest {
  kind: InsertDialogKind
  /** The node being edited, so saving updates it in place. */
  pos?: number
  initial?: string
}

/**
 * The editor's own UI that actions open. The component supplies these; a
 * headless editor gets simple fallbacks.
 */
export interface EditorUiHandlers {
  openDialog: (request: InsertDialogRequest) => void
  /** Opens the file picker and inserts the chosen images. */
  pickImages: () => void
  toggleFind: (open?: boolean) => void
  toggleOutline: (open?: boolean) => void
  toggleFullscreen: (open?: boolean) => void
  /** Dims every block but the one being edited. */
  toggleFocusMode: (on?: boolean) => void
  /** Opens the AI panel's prompt box for "Ask AI…". */
  askAI: () => void
  /** Which panels and views are on, for the toolbar's pressed states. */
  viewState: () => EditorViewState
}

export interface EditorViewState {
  find: boolean
  outline: boolean
  fullscreen: boolean
  focusMode: boolean
}

/** Props every replaceable UI area (`components`) receives. */
export interface EditorSlotProps {
  controller: EditorController
  editor: Editor
}

export type { AnyExtension, EditorAIConfig }

import * as React from "react"
import type { AnyExtension } from "@tiptap/core"
import { useEditor, type Editor } from "@tiptap/react"

import { createAIActions } from "./ai/ai-actions"
import type { AIController } from "./ai/ai-controller"
import type { ActionRegistry } from "./core/action-registry"
import { createBuiltInActions } from "./core/builtin-actions"
import { resolveFeatures } from "./core/features"
import { isAlive } from "./core/lifecycle"
import { createEditorExtensions } from "./extensions"
import { EditorRuntime } from "./runtime"
import type {
  EditorAction,
  EditorAIConfig,
  EditorController,
  EditorError,
  EditorFeatures,
  EditorPreset,
  EditorSelection,
  EditorUiHandlers,
  MentionSource,
  ResolvedEditorFeatures,
  UploadHandler,
  UrlPolicy,
} from "./types"

export interface UseRichTextEditorOptions {
  /** Markdown, controlled. Don't pass it with `defaultValue`. */
  value?: string
  /** Markdown the editor starts with, uncontrolled. */
  defaultValue?: string
  /** The document as Markdown, after edits and successful programmatic changes. */
  onChange?: (markdown: string) => void
  /** Wait this many ms after typing stops before `onChange` (it still flushes on blur). Default 0. */
  onChangeDebounce?: number

  readOnly?: boolean
  disabled?: boolean
  autoFocus?: boolean | "start" | "end"
  placeholder?: string

  /** Which features start on; `features` overrides single ones. Default `standard`. */
  preset?: EditorPreset
  features?: EditorFeatures
  /** The most characters the document may hold; typing stops there. */
  maxLength?: number

  /** Commands for toolbars, menus, `/` and `executeAction`. */
  actions?: EditorAction[]
  /** More Tiptap extensions. Keep the array stable (module scope or useMemo). */
  extensions?: AnyExtension[]
  ai?: EditorAIConfig

  /** Enables `@` mentions, suggesting what the source returns. */
  mentions?: MentionSource
  /** Stores added images and returns their URLs; without it they're inlined. */
  onUpload?: UploadHandler
  /** Largest image that can be added, in bytes. Default 10 MB. */
  maxFileSize?: number
  /** Which link and image URLs are allowed. */
  urlPolicy?: UrlPolicy

  onFocus?: () => void
  onBlur?: () => void
  onSelectionChange?: (selection: EditorSelection) => void
  onError?: (error: EditorError) => void
  /** Called once, when the editor is ready, with its controller. */
  onReady?: (controller: EditorController) => void

  /** Attributes for the editable element (role, aria-*). */
  attributes?: Record<string, string>
  /** The UI the built-in actions open; a headless editor gets fallbacks. */
  ui?: Partial<EditorUiHandlers>
}

export interface RichTextEditorInstance {
  editor: Editor
  controller: EditorController
  registry: ActionRegistry
  ai: AIController
  features: ResolvedEditorFeatures
  ui: () => EditorUiHandlers
  urlPolicy: () => UrlPolicy
}

/**
 * The editor without its UI: the Tiptap instance, its controller, the action
 * registry and AI, with Markdown in and out. `RichTextEditor` is built on
 * it; use it directly for a fully custom interface, rendering
 * `RichTextEditorProvider` and `RichTextEditorContent` from `./headless`.
 */
export function useRichTextEditor(
  options: UseRichTextEditorOptions
): RichTextEditorInstance {
  const {
    value,
    defaultValue,
    readOnly = false,
    disabled = false,
    autoFocus = false,
    preset = "standard",
    features: featureOverrides,
    maxLength,
    actions,
    extensions: customExtensions,
    ai: aiConfig,
    mentions,
    urlPolicy,
    attributes,
  } = options

  const featuresKey = JSON.stringify(resolveFeatures(preset, featureOverrides))
  const features = React.useMemo<ResolvedEditorFeatures>(
    () => JSON.parse(featuresKey),
    [featuresKey]
  )
  const editable = !readOnly && !disabled

  // Stable for the component's lifetime; it reads the latest options.
  const [runtime] = React.useState(() => new EditorRuntime(options))
  React.useLayoutEffect(() => {
    runtime.setOptions(options)
  })
  const { registry, controller, ai, handlers, ui } = runtime

  // Built-in and AI actions follow the features and the AI setup; the
  // app's own follow the `actions` prop.
  const aiKey = JSON.stringify([
    aiConfig?.enabled,
    aiConfig?.allowCustomPrompts,
    aiConfig?.actions?.map(({ id, label, requiresSelection, description }) => [
      id,
      label,
      requiresSelection,
      description,
    ]),
  ])
  React.useLayoutEffect(() => {
    registry.setBuiltIns([
      ...createBuiltInActions(features, ui),
      ...createAIActions(ai, ui),
    ])
  }, [registry, ai, ui, features, aiKey])
  React.useLayoutEffect(() => {
    registry.setCustom(actions ?? [])
  })

  const hasMentions = Boolean(mentions)
  const extensions = React.useMemo(
    () =>
      createEditorExtensions({
        features,
        maxLength,
        mentions: hasMentions,
        urlPolicy,
        handlers,
        extensions: customExtensions,
      }),
    [features, maxLength, hasMentions, urlPolicy, handlers, customExtensions]
  )

  // A rebuilt editor (new features) starts from the current document.
  const content = runtime.currentContent(value ?? defaultValue ?? "")

  const editor = useEditor(
    {
      extensions,
      content,
      contentType: "markdown",
      // The editor only renders in the browser (it loads lazily there).
      immediatelyRender: true,
      editable,
      autofocus: autoFocus === true ? "end" : autoFocus || false,
      shouldRerenderOnTransaction: false,
      // Without Markdown shortcuts, typography and emoticons still convert.
      enableInputRules: features.markdownShortcuts
        ? true
        : ["typography", "emoji"],
      editorProps: { attributes: attributes ?? {} },
      onUpdate: () => runtime.sync.changed(),
      onSelectionUpdate: () => runtime.selectionChanged(),
      onBeforeCreate: ({ editor }) => runtime.setEditor(editor),
      onFocus: () => runtime.focused(),
      onBlur: () => runtime.blurred(),
    },
    [extensions]
  )
  // StrictMode can build an editor twice and keep either: the controller
  // follows the one React renders, not the last one built.
  runtime.setEditor(editor)

  // Once per component, not per rebuilt editor: the controller outlives them.
  React.useEffect(() => {
    runtime.notifyReady()
  }, [runtime])

  const bothValues = value !== undefined && defaultValue !== undefined
  React.useEffect(() => {
    if (!bothValues) return
    runtime.onError({
      code: "invalid-props",
      message:
        "Pass either value (controlled) or defaultValue (uncontrolled), not both; value wins.",
    })
  }, [bothValues, runtime])

  // A new `value` from outside replaces the document; our own echo doesn't.
  React.useEffect(() => {
    if (value !== undefined && isAlive(editor)) runtime.receive(editor, value)
  }, [editor, value, runtime])

  React.useEffect(() => {
    editor.setEditable(editable, false)
  }, [editor, editable])

  const attributesKey = JSON.stringify(attributes ?? {})
  React.useEffect(() => {
    editor.setOptions({
      editorProps: { attributes: JSON.parse(attributesKey) },
    })
  }, [editor, attributesKey])

  React.useEffect(() => () => runtime.dispose(), [runtime])

  return {
    editor,
    controller,
    registry,
    ai,
    features,
    ui,
    urlPolicy: runtime.policy,
  }
}
